window.RESPI_SOURCE_MOCKS={"exams":[{"id":"mock1","title":"Mock Exam 1","subtitle":"100 source-based MCQs · 2 hours","level":"Mixed","timeMinutes":120,"count":100,"description":"Questions 1–100 from the first complete photographed questionnaire. Original stems and options preserved; answers reviewed.","icon":"clipboard-list"},{"id":"mock2","title":"Mock Exam 2","subtitle":"100 source-based MCQs · 2 hours","level":"Mixed","timeMinutes":120,"count":100,"description":"The second photographed questionnaire (96 questions), completed with 4 intact MCQs from the accompanying VIMS notes. Source choices preserved.","icon":"clipboard-check"}],"questions":[{"id":"PDF1-001","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 13","sourcePage":13,"sourceNumber":"1","difficulty":"mixed","topic":"Lung volumes, gas laws & mechanics","question":"Closing capacity is the lung volume at which small airways begin to close. Which of the following is TRUE about closing capacity?","options":["It decreases with age.","It is always higher than the Functional Residual Capacity in healthy lungs.","It increases with age.","If closing capacity is less than FRC, airways close during normal breathing."],"correct":2,"explanation":"Closing capacity rises with age; small airway closure occurs when closing capacity exceeds FRC.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":1,"auditFlag":false},{"id":"PDF1-002","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 13","sourcePage":13,"sourceNumber":"2","difficulty":"mixed","topic":"Lung volumes, gas laws & mechanics","question":"Functional Residual Capacity (FRC) is defined as:","options":["The lung volume remaining after a passive normal exhalation.","The lung volume remaining after a forced maximal exhalation.","The sum of tidal volume and inspiratory reserve volume.","A volume that can be measured directly by spirometry."],"correct":0,"explanation":"FRC is the volume left after a normal passive expiration.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":2,"auditFlag":false},{"id":"PDF1-003","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 13","sourcePage":13,"sourceNumber":"3","difficulty":"mixed","topic":"Lung volumes, gas laws & mechanics","question":"Which of the following factors would increase FRC?","options":["Late-term pregnancy.","Emphysema.","Obesity.","Supine posture."],"correct":1,"explanation":"Emphysema increases hyperinflation and residual gas volume.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":3,"auditFlag":false},{"id":"PDF1-004","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 13","sourcePage":13,"sourceNumber":"4","difficulty":"mixed","topic":"Lung volumes, gas laws & mechanics","question":"A ventilated patient has a tidal volume of 500 mL, plateau pressure 25 cm H₂O, and PEEP 5 cm H₂O. The static compliance of the respiratory system is approximately:","options":["10 mL/cm H₂O.","25 mL/cm H₂O.","100 mL/cm H₂O.","20 mL/cm H₂O."],"correct":1,"explanation":"Static compliance = 500/(25 − 5) = 25 mL/cm H₂O.","answerOrigin":"marked in source","calculation":true,"sourceFile":"Mock exam preparation .pdf","originQuestion":4,"auditFlag":false},{"id":"PDF1-005","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 13","sourcePage":13,"sourceNumber":"5","difficulty":"mixed","topic":"Lung volumes, gas laws & mechanics","question":"In an average adult, anatomical dead space is approximately:","options":["150 mL.","500 mL.","5 L.","50 mL."],"correct":0,"explanation":"Average adult anatomical dead space is approximately 150 mL.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":5,"auditFlag":false},{"id":"PDF1-006","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 13","sourcePage":13,"sourceNumber":"6","difficulty":"mixed","topic":"Lung volumes, gas laws & mechanics","question":"Hypoxic pulmonary vasoconstriction serves to:","options":["Divert blood flow away from poorly ventilated alveoli, reducing shunt.","Improve systemic oxygenation by dilating pulmonary vessels.","Lower pulmonary artery pressure during hypoxemia.","Cause bronchodilation during hypoxia."],"correct":0,"explanation":"Vasoconstriction in hypoxic lung regions redistributes pulmonary perfusion.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":6,"auditFlag":false},{"id":"PDF1-007","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 13","sourcePage":13,"sourceNumber":"7","difficulty":"mixed","topic":"Lung volumes, gas laws & mechanics","question":"One effect of initiating positive-pressure ventilation is:","options":["Increased cardiac preload and output.","Decreased venous return and possible hypotension.","Lower intrathoracic pressure during inspiration.","Reflex bradycardia via vagal stimulation."],"correct":1,"explanation":"Higher intrathoracic pressure can decrease preload and blood pressure.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":7,"auditFlag":false},{"id":"PDF1-008","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 13","sourcePage":13,"sourceNumber":"8","difficulty":"mixed","topic":"Lung volumes, gas laws & mechanics","question":"Dalton's Law states that:","options":["Gas volume is directly proportional to absolute temperature.","Pressure and volume are inversely related at constant temperature.","The total pressure of a gas mixture equals the sum of the partial pressures of its components.","Gas solubility in liquid is proportional to its partial pressure."],"correct":2,"explanation":"Dalton's law is the sum-of-partial-pressures relationship.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":8,"auditFlag":false},{"id":"PDF1-009","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 12","sourcePage":12,"sourceNumber":"9","difficulty":"mixed","topic":"Lung volumes, gas laws & mechanics","question":"Boyle's Law describes:","options":["The direct proportionality of volume to temperature at constant pressure.","An inverse relationship between gas pressure and volume at constant temperature.","The equivalence of the sum of partial pressures to total pressure.","The relationship between gas solubility and atmospheric pressure."],"correct":1,"explanation":"For a fixed amount of gas at constant temperature, P×V is constant.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":9,"auditFlag":false},{"id":"PDF1-010","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 12","sourcePage":12,"sourceNumber":"10","difficulty":"mixed","topic":"Gas exchange & respiratory physiology","question":"During normal nasal breathing, inspired air becomes fully (100%) humidified at body temperature by the time it reaches the:","options":["Alveoli.","Oropharynx.","Nasopharynx.","Trachea (carina level)."],"correct":3,"explanation":"The isothermic saturation boundary lies in the respiratory tract near the carina.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":10,"auditFlag":false},{"id":"PDF1-011","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 12","sourcePage":12,"sourceNumber":"11","difficulty":"mixed","topic":"Gas exchange & respiratory physiology","question":"Approximately what PaO₂ corresponds to an arterial oxygen saturation (SaO₂) of 90% (on the oxyhemoglobin dissociation curve)?","options":["40 mmHg.","60 mmHg.","80 mmHg.","100 mmHg."],"correct":1,"explanation":"Around PaO₂ 60 mmHg, arterial saturation is approximately 90%.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":11,"auditFlag":false},{"id":"PDF1-012","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 12","sourcePage":12,"sourceNumber":"12","difficulty":"mixed","topic":"Gas exchange & respiratory physiology","question":"Assuming hemoglobin 15 g/dL and full arterial O₂ saturation, the oxygen content of arterial blood (CaO₂) is roughly:","options":["5 mL O₂ per 100 mL blood.","15 mL O₂ per 100 mL blood.","20 mL O₂ per 100 mL blood.","10 mL O₂ per 100 mL blood."],"correct":2,"explanation":"1.34 × 15 × 1.0 ≈20.1 mL O₂/dL.","answerOrigin":"marked in source","calculation":true,"sourceFile":"Mock exam preparation .pdf","originQuestion":12,"auditFlag":false},{"id":"PDF1-013","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 12","sourcePage":12,"sourceNumber":"13","difficulty":"mixed","topic":"Gas exchange & respiratory physiology","question":"Which of the following tends to increase CO₂ production in the body?","options":["Sedation and hypothermia.","Sepsis with fever.","Mechanical ventilation.","Hypothyroidism."],"correct":1,"explanation":"Fever and sepsis can increase metabolic rate and CO₂ production.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":13,"auditFlag":false},{"id":"PDF1-014","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 12","sourcePage":12,"sourceNumber":"14","difficulty":"mixed","topic":"Gas exchange & respiratory physiology","question":"During an apnea test for brain death, PaCO₂ rises by ~3 mmHg per minute of apnea. If starting PaCO₂ is 28 mmHg, approximately how long must the patient be apneic to reach 60 mmHg?","options":["8 minutes.","11 minutes.","20 minutes.","4 minutes."],"correct":1,"explanation":"(60−28)/3 ≈ 10.7 minutes, nearest 11 minutes; this is a theoretical calculation, not a protocol for clinical apnea testing.","answerOrigin":"marked in source","calculation":true,"sourceFile":"Mock exam preparation .pdf","originQuestion":14,"auditFlag":false},{"id":"PDF1-015","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 12","sourcePage":12,"sourceNumber":"15","difficulty":"mixed","topic":"Gas exchange & respiratory physiology","question":"A low ventilation-perfusion (V/Q) ratio in a lung region will result in:","options":["Systemic arterial hyperoxia.","Low PaCO₂.","Low PaO₂ due to shunting.","Increased dead space ventilation."],"correct":2,"explanation":"Low V/Q decreases oxygenation, creating a shunt-like effect.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":15,"auditFlag":false},{"id":"PDF1-016","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 11","sourcePage":11,"sourceNumber":"16","difficulty":"mixed","topic":"Gas exchange & respiratory physiology","question":"An abnormally high alveolar-arterial (A-a) O₂ gradient suggests:","options":["V/Q mismatch (shunt) in the lungs.","Carbon monoxide poisoning.","Pure hypoventilation as cause of hypoxemia.","Low barometric pressure."],"correct":0,"explanation":"An elevated A–a oxygen gradient suggests impaired gas exchange, such as V/Q mismatch or shunt.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":16,"auditFlag":false},{"id":"PDF1-017","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 11","sourcePage":11,"sourceNumber":"17","difficulty":"mixed","topic":"Gas exchange & respiratory physiology","question":"A 75-year-old on FiO₂ 1.0 has an alveolar O₂ (PAO₂) of ~663 mmHg but an arterial PaO₂ of only 60 mmHg. The approximate A–a gradient is:","options":["300 mmHg.","100 mmHg.","60 mmHg.","600 mmHg."],"correct":3,"explanation":"A–a = 663−60=603 mmHg, approximately 600.","answerOrigin":"marked in source","calculation":true,"sourceFile":"Mock exam preparation .pdf","originQuestion":17,"auditFlag":false},{"id":"PDF1-018","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 11","sourcePage":11,"sourceNumber":"18","difficulty":"mixed","topic":"Gas exchange & respiratory physiology","question":"In a resting healthy person, intrapleural pressure at end-expiration is about:","options":["-5 cm H₂O.","0 cm H₂O (atmospheric).","+5 cm H₂O.","-30 cm H₂O."],"correct":0,"explanation":"Normal intrapleural pressure at end expiration is negative, about −5 cm H₂O.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":18,"auditFlag":false},{"id":"PDF1-019","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 11","sourcePage":11,"sourceNumber":"19","difficulty":"mixed","topic":"Gas exchange & respiratory physiology","question":"All of the following will shift the oxyhemoglobin dissociation curve to the right (decreased affinity) EXCEPT:","options":["Acidosis (low pH).","Hypothermia.","Hypercapnia (high CO₂).","Increased 2,3-DPG."],"correct":1,"explanation":"Hypothermia shifts the curve left; fever, acidosis, hypercapnia and increased 2,3-DPG shift it right.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":19,"auditFlag":false},{"id":"PDF1-020","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 11","sourcePage":11,"sourceNumber":"20","difficulty":"mixed","topic":"Gas exchange & respiratory physiology","question":"In a healthy adult, the primary drive to breathe is stimulated by:","options":["Low PaO₂ acting on central chemoreceptors.","Pain signals via mechanoreceptors.","Elevated PaCO₂ acting on central chemoreceptors.","Voluntary cortical control."],"correct":2,"explanation":"Raised PaCO₂ increases CSF hydrogen ions sensed by central chemoreceptors.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":20,"auditFlag":false},{"id":"PDF1-021","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 11","sourcePage":11,"sourceNumber":"21","difficulty":"mixed","topic":"Gas exchange & respiratory physiology","question":"In patients with chronic CO₂ retention (e.g., severe COPD), giving excessive supplemental O₂ can lead to hypoventilation because:","options":["Oxygen is a direct respiratory depressant.","High O₂ increases metabolic CO₂ production.","Oxygen causes bronchoconstriction.","Their ventilatory drive relies on hypoxemia (low O₂)."],"correct":3,"explanation":"This is the answer indicated in the source. In practice, worsening hypercapnia also importantly involves V/Q redistribution and the Haldane effect; hypoxic-drive suppression alone is incomplete.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":21,"auditFlag":true,"auditNote":"Source attributes oxygen-related CO2 retention to loss of hypoxic drive alone; incomplete physiology."},{"id":"PDF1-022","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 11","sourcePage":11,"sourceNumber":"22","difficulty":"mixed","topic":"Gas exchange & respiratory physiology","question":"A normal resting tidal volume in an adult is approximately:","options":["7 mL/kg.","Equal to the vital capacity.","100 mL total.","15 mL/kg."],"correct":0,"explanation":"Resting VT is approximately 6–8 mL/kg.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":22,"auditFlag":false},{"id":"PDF1-023","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 11","sourcePage":11,"sourceNumber":"23","difficulty":"mixed","topic":"Gas exchange & respiratory physiology","question":"Which lung volume cannot be measured by simple spirometry?","options":["Tidal Volume.","Vital Capacity.","Expiratory Reserve Volume.","Residual Volume."],"correct":3,"explanation":"Simple spirometry cannot measure air that remains trapped after maximal expiration.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":23,"auditFlag":false},{"id":"PDF1-024","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 10","sourcePage":10,"sourceNumber":"24","difficulty":"mixed","topic":"Gas exchange & respiratory physiology","question":"The normal alveolar PO₂ on room air at sea level is approximately:","options":["100 mmHg.","150 mmHg.","40 mmHg.","760 mmHg."],"correct":0,"explanation":"Normal alveolar PO₂ at sea level on room air is about 100 mmHg.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":24,"auditFlag":false},{"id":"PDF1-025","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 10","sourcePage":10,"sourceNumber":"25","difficulty":"mixed","topic":"Gas exchange & respiratory physiology","question":"In severe anemia, arterial blood gases may show a normal PaO₂, but oxygen content is low because:","options":["O₂ content depends mainly on hemoglobin-bound O₂, which is reduced in anemia.","Anemia causes PaO₂ to drop in proportion to hemoglobin loss.","PaO₂ directly reflects hemoglobin concentration.","Oxygen dissolves poorly in plasma."],"correct":0,"explanation":"Most arterial oxygen is carried bound to Hb, so low Hb reduces content without necessarily lowering PaO₂.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":25,"auditFlag":false},{"id":"PDF1-026","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 10","sourcePage":10,"sourceNumber":"26","difficulty":"mixed","topic":"Gas exchange & respiratory physiology","question":"The normal Functional Residual Capacity (FRC) in a healthy adult male is approximately:","options":["70 mL/kg.","30 mL/kg.","10 mL/kg.","50 mL/kg."],"correct":1,"explanation":"A commonly used resting FRC approximation is 30 mL/kg.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":26,"auditFlag":false},{"id":"PDF1-027","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 10","sourcePage":10,"sourceNumber":"27","difficulty":"mixed","topic":"Gas exchange & respiratory physiology","question":"Opioid analgesics can cause respiratory depression by:","options":["Increasing CO₂ production via metabolism.","Causing diffuse bronchospasm.","Paralyzing the diaphragm muscle.","Blunting the brainstem's sensitivity to CO₂ (raising the CO₂ threshold for ventilation)."],"correct":3,"explanation":"Opioids suppress brainstem respiratory responsiveness to carbon dioxide.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":27,"auditFlag":false},{"id":"PDF1-028","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 10","sourcePage":10,"sourceNumber":"28","difficulty":"mixed","topic":"Gas exchange & respiratory physiology","question":"If alveolar ventilation is halved (with CO₂ production constant), the PaCO₂ will:","options":["Approximately double.","Remain unchanged.","Decrease by ~50%.","Decrease to near zero."],"correct":0,"explanation":"PaCO₂ is inversely proportional to alveolar ventilation if CO₂ production remains constant.","answerOrigin":"marked in source","calculation":true,"sourceFile":"Mock exam preparation .pdf","originQuestion":28,"auditFlag":false},{"id":"PDF1-029","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 10","sourcePage":10,"sourceNumber":"29","difficulty":"mixed","topic":"Gas exchange & respiratory physiology","question":"In late pregnancy, the Functional Residual Capacity (FRC):","options":["Decreases compared to non-pregnant values.","Is unchanged from normal.","Increases due to elevated diaphragm position.","Exceeds closing capacity."],"correct":0,"explanation":"A higher diaphragm and reduced expiratory reserve reduce FRC.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":29,"auditFlag":false},{"id":"PDF1-030","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 10","sourcePage":10,"sourceNumber":"30","difficulty":"mixed","topic":"Airway assessment & intubation","question":"The optimal head position for direct laryngoscopy during intubation is:","options":["The “sniffing” position (neck flexed, head extended).","Trendelenburg position.","Full neck extension with head flat on bed.","Lateral decubitus position."],"correct":0,"explanation":"The sniffing position combines lower cervical flexion with atlanto-occipital extension.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":30,"auditFlag":false},{"id":"PDF1-031","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 10","sourcePage":10,"sourceNumber":"31","difficulty":"mixed","topic":"Airway assessment & intubation","question":"Which of the following is a known risk factor for difficult intubation?","options":["Mallampati Class I airway.","Short neck with full range of motion.","Edentulous (no teeth) patient.","History of head and neck radiotherapy."],"correct":3,"explanation":"Prior head/neck radiotherapy can reduce neck mobility and deform upper-airway anatomy.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":31,"auditFlag":false},{"id":"PDF1-032","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 9","sourcePage":9,"sourceNumber":"32","difficulty":"mixed","topic":"Airway assessment & intubation","question":"Rapid Sequence Intubation (RSI) includes applying cricoid pressure to:","options":["Improve visualization of the vocal cords.","Facilitate endotracheal tube passage through the glottis.","Compress the esophagus and reduce aspiration risk.","Stimulate spontaneous swallowing."],"correct":2,"explanation":"This describes the historical rationale for cricoid pressure in RSI; routine application is debated and should follow local protocols.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":32,"auditFlag":true,"auditNote":"Routine cricoid pressure in RSI is no longer universally recommended."},{"id":"PDF1-033","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 9","sourcePage":9,"sourceNumber":"33","difficulty":"mixed","topic":"Airway assessment & intubation","question":"The endotracheal tube cuff pressure should generally be maintained around:","options":["20–30 cm H₂O.","100 cm H₂O.","5 cm H₂O.","50 cm H₂O."],"correct":0,"explanation":"A cuff pressure of 20–30 cm H₂O balances sealing with avoidance of tracheal injury.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":33,"auditFlag":false},{"id":"PDF1-034","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 9","sourcePage":9,"sourceNumber":"34","difficulty":"mixed","topic":"Airway assessment & intubation","question":"Mallampati Class IV airway is characterized by:","options":["Only the hard palate visible (no uvula or soft palate seen).","Full visibility of the tonsils, uvula, and soft palate.","Partial visibility of the uvula.","Vocal cords clearly visible on mouth opening."],"correct":0,"explanation":"Class IV shows only hard palate.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":34,"auditFlag":false},{"id":"PDF1-035","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 9","sourcePage":9,"sourceNumber":"35","difficulty":"mixed","topic":"Airway assessment & intubation","question":"On chest X-ray of an intubated patient, the endotracheal tube tip is seen in the right main bronchus. The appropriate management is to:","options":["Clamp the right bronchus.","Advance the tube further in.","Withdraw the endotracheal tube slightly and recheck position.","Leave it if breath sounds are present."],"correct":2,"explanation":"A mainstem ETT requires controlled withdrawal and reassessment of depth/position.","answerOrigin":"verified against course materials","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":35,"auditFlag":true,"auditNote":"Annotation not relied on; answer clinically verified (withdraw mainstem ETT)."},{"id":"PDF1-036","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 9","sourcePage":9,"sourceNumber":"36","difficulty":"mixed","topic":"Airway assessment & intubation","question":"A patient with severe head trauma has a Glasgow Coma Scale score of 7 and is unable to protect the airway. The best course of action is:","options":["Place the patient in recovery position and observe.","Intubate and initiate mechanical ventilation.","Use an oropharyngeal airway without intubation.","Apply high-flow nasal cannula oxygen."],"correct":1,"explanation":"Failure to protect airway in severe neurologic injury requires definitive airway assessment and management.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":36,"auditFlag":false},{"id":"PDF1-037","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 9","sourcePage":9,"sourceNumber":"37","difficulty":"mixed","topic":"Airway assessment & intubation","question":"The most reliable method to confirm correct endotracheal tube placement in the trachea is:","options":["Detection of CO₂ on capnography (sustained end-tidal CO₂ waveform).","Auscultation of breath sounds alone.","Bilateral chest rise on ventilation.","Fogging of the ETT with exhalation."],"correct":0,"explanation":"Sustained waveform capnography is the most reliable bedside confirmation.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":37,"auditFlag":false},{"id":"PDF1-038","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 9","sourcePage":9,"sourceNumber":"38","difficulty":"mixed","topic":"Airway assessment & intubation","question":"While suctioning an intubated patient, you cannot pass the suction catheter through the endotracheal tube. The FIRST action should be to:","options":["Apply more suction pressure.","Instill saline and attempt again.","Suspect obstruction – check the tube for kinks or blockage and prepare to replace it if needed.","Wait and retry later."],"correct":2,"explanation":"Resistance to catheter passage raises concern for blockage/kink requiring prompt airway assessment.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":38,"auditFlag":false},{"id":"PDF1-039","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 9","sourcePage":9,"sourceNumber":"39","difficulty":"mixed","topic":"Ventilator modes & settings","question":"In pressure-controlled ventilation, if the patient's lung compliance decreases significantly (and other settings remain constant), what will happen?","options":["Delivered tidal volume will decrease.","Peak inspiratory pressure will rise.","Set inspiratory pressure will automatically increase to compensate.","Tidal volume remains unchanged (pressure is fixed)."],"correct":0,"explanation":"At fixed pressure, lower compliance yields lower tidal volume.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":39,"auditFlag":false},{"id":"PDF1-040","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 8","sourcePage":8,"sourceNumber":"40","difficulty":"mixed","topic":"Ventilator modes & settings","question":"Which ventilator trigger method generally results in the lowest patient work of breathing?","options":["Flow triggering.","Time triggering.","Pressure triggering.","Manual (operator) triggering."],"correct":0,"explanation":"Flow triggering generally has lower triggering work than pressure-triggering, though differences with modern ventilators may be small.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":40,"auditFlag":false},{"id":"PDF1-041","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 8","sourcePage":8,"sourceNumber":"41","difficulty":"mixed","topic":"Ventilator modes & settings","question":"In volume assist-control (AC) ventilation, if a patient initiates an extra breath above the set rate, the ventilator will:","options":["Deliver the full preset tidal volume for that breath.","Provide only a small pressure support for that breath.","Not respond (only set breaths are delivered).","Cycle immediately to exhalation (terminating the breath early)."],"correct":0,"explanation":"In volume AC, patient-triggered breaths still receive set-volume mandatory breaths.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":41,"auditFlag":false},{"id":"PDF1-042","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 8","sourcePage":8,"sourceNumber":"42","difficulty":"mixed","topic":"Ventilator modes & settings","question":"Synchronized Intermittent Mandatory Ventilation (SIMV) is best described as:","options":["A mode providing a set number of mandatory breaths while allowing spontaneous breaths between them.","A mode in which every breath (spontaneous or mandatory) is fully machine-delivered.","Ventilation using an automatically adjusting minute volume.","A purely patient-triggered pressure support mode."],"correct":0,"explanation":"SIMV schedules mandatory breaths while permitting spontaneous breaths between them.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":42,"auditFlag":false},{"id":"PDF1-043","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 8","sourcePage":8,"sourceNumber":"43","difficulty":"mixed","topic":"Ventilator modes & settings","question":"Pressure Support Ventilation (PSV) can be characterized by:","options":["Patient-triggered breaths that are pressure-limited and flow-cycled.","Delivery of a fixed tidal volume on each breath.","Time-cycled mandatory breaths at a set rate.","Not being useful as a weaning mode."],"correct":0,"explanation":"Pressure support is typically patient-triggered and flow-cycled.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":43,"auditFlag":false},{"id":"PDF1-044","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 8","sourcePage":8,"sourceNumber":"44","difficulty":"mixed","topic":"Ventilator modes & settings","question":"Increasing the set inspiratory flow rate on a ventilator (keeping tidal volume the same) will:","options":["Shorten inspiratory time and allow a longer expiratory time.","Lengthen inspiratory time (increasing I:E ratio).","Decrease peak inspiratory pressure.","Have no effect on the I:E ratio."],"correct":0,"explanation":"At fixed VT, higher inspiratory flow delivers volume faster and extends exhalation.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":44,"auditFlag":false},{"id":"PDF1-045","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 8","sourcePage":8,"sourceNumber":"45","difficulty":"mixed","topic":"Ventilator modes & settings","question":"Applying Positive End-Expiratory Pressure (PEEP) helps to:","options":["Increase Functional Residual Capacity and improve oxygenation.","Decrease mean airway pressure.","Collapse alveoli at end-expiration.","Reduce intrathoracic pressure."],"correct":0,"explanation":"PEEP prevents expiratory derecruitment and improves FRC.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":45,"auditFlag":false},{"id":"PDF1-046","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 8","sourcePage":8,"sourceNumber":"46","difficulty":"mixed","topic":"Ventilator modes & settings","question":"In managing a patient with acute severe COPD on mechanical ventilation, an appropriate I:E ratio would be:","options":["1:3 or 1:4 to prolong expiration.","1:2 (no change from normal).","1:1 to normalize PaCO₂.","2:1 (inverse ratio ventilation)."],"correct":0,"explanation":"Longer expiration reduces air trapping in obstructive physiology.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":46,"auditFlag":false},{"id":"PDF1-047","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 8","sourcePage":8,"sourceNumber":"47","difficulty":"mixed","topic":"Ventilator modes & settings","question":"If a patient requires FiO₂ > 0.6 (60%) to maintain adequate oxygenation, a reasonable next step is to:","options":["Increase PEEP to improve oxygenation.","Increase tidal volume above 10 mL/kg.","Tolerate lower oxygen saturation.","Use a nonrebreather mask instead of the ventilator."],"correct":0,"explanation":"Consider PEEP optimisation when high inspired oxygen is required for recruitment.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":47,"auditFlag":false},{"id":"PDF1-048","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 7","sourcePage":7,"sourceNumber":"48","difficulty":"mixed","topic":"Ventilator modes & settings","question":"Continuous Positive Airway Pressure (CPAP) is best described as:","options":["Continuous positive pressure throughout the respiratory cycle in a spontaneously breathing patient (essentially PEEP without machine breaths).","Alternating high and low pressures for inspiration and expiration (BiPAP).","Positive pressure during inspiration only.","High-frequency oscillatory ventilation."],"correct":0,"explanation":"CPAP applies a single continuous positive pressure.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":48,"auditFlag":false},{"id":"PDF1-049","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 7","sourcePage":7,"sourceNumber":"49","difficulty":"mixed","topic":"Ventilator modes & settings","question":"Bi-level Positive Airway Pressure (BiPAP) provides:","options":["Two levels of positive pressure – a higher inspiratory pressure and a lower expiratory pressure (PEEP).","Continuous distending pressure with no pressure difference between inspiration and expiration.","Mandatory breaths at a set tidal volume.","Negative pressure on exhalation to aid CO₂ removal."],"correct":0,"explanation":"BiPAP uses IPAP greater than EPAP.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":49,"auditFlag":false},{"id":"PDF1-050","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 7","sourcePage":7,"sourceNumber":"50","difficulty":"mixed","topic":"Ventilator modes & settings","question":"Which statement correctly distinguishes Volume-Controlled (VC) vs. Pressure-Controlled (PC) ventilation?","options":["There is no practical difference between VC and PC modes.","VC delivers a set tidal volume (volume-targeted), whereas PC delivers a set inspiratory pressure (pressure-targeted).","In VC mode the tidal volume varies with lung compliance, while in PC mode tidal volume is fixed.","VC results in a constant peak pressure each breath, whereas PC guarantees a fixed tidal volume each breath."],"correct":1,"explanation":"VC controls delivered VT and PC controls inspiratory pressure.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":50,"auditFlag":false},{"id":"PDF1-051","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 7","sourcePage":7,"sourceNumber":"51","difficulty":"mixed","topic":"Ventilator modes & settings","question":"A high peak airway pressure alarm is MOST likely caused by:","options":["A large system leak around the tube cuff.","Circuit disconnection.","Extubation of the patient.","Increased airway resistance or obstruction (e.g., bronchospasm, secretions, ETT kink)."],"correct":3,"explanation":"Increased resistance or obstruction causes higher inspiratory pressures.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":51,"auditFlag":false},{"id":"PDF1-052","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 7","sourcePage":7,"sourceNumber":"52","difficulty":"mixed","topic":"Ventilator modes & settings","question":"A low pressure (or low exhaled volume) alarm on the ventilator is usually triggered by:","options":["A disconnection or leak in the circuit.","Biting on the endotracheal tube.","Bronchospasm.","Water in the ventilator tubing."],"correct":0,"explanation":"Loss of circuit integrity lowers returned volume or pressure.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":52,"auditFlag":false},{"id":"PDF1-053","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 7","sourcePage":7,"sourceNumber":"53","difficulty":"mixed","topic":"Ventilator modes & settings","question":"A large difference between peak inspiratory pressure (PIP) and plateau pressure (Pplat) is most indicative of:","options":["High airway resistance (e.g., asthma, mucus plugging).","Decreased lung compliance.","Circuit leak or disconnection.","Patient effort during the breath."],"correct":0,"explanation":"PIP−Pplat is the resistive pressure component during constant flow.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":53,"auditFlag":false},{"id":"PDF1-054","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 6","sourcePage":6,"sourceNumber":"54","difficulty":"mixed","topic":"Ventilator waveforms & troubleshooting","question":"On the ventilator flow-time waveform, the presence of auto-PEEP is indicated by:","options":["Expiratory flow not returning to zero before the next breath (incomplete exhalation).","A spike of inspiratory flow after the breath cycles off.","A prolonged pause at end-expiration at zero flow.","Oscillations in the expiratory flow trace."],"correct":0,"explanation":"Incomplete exhalation before the next inspiration indicates air trapping.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":54,"auditFlag":false},{"id":"PDF1-055","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 6","sourcePage":6,"sourceNumber":"55","difficulty":"mixed","topic":"Ventilator waveforms & troubleshooting","question":"A \"scooped\" or concave expiratory flow-volume loop (scalloped expiratory curve) is characteristic of:","options":["Obstructive airway disease (e.g., COPD, asthma).","Normal expiration.","Stiff lungs (e.g., fibrosis, ARDS).","Ventilator circuit leak."],"correct":0,"explanation":"A concave expiratory limb is typical of obstructive airflow limitation.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":55,"auditFlag":false},{"id":"PDF1-056","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 6","sourcePage":6,"sourceNumber":"56","difficulty":"mixed","topic":"Ventilator waveforms & troubleshooting","question":"A ventilated trauma patient suddenly develops hypotension and high peak airway pressures. The most likely cause is:","options":["Tension pneumothorax.","Pulmonary embolism.","Accidental extubation.","Ventilator machine failure."],"correct":0,"explanation":"Tension pneumothorax may abruptly elevate airway pressures and impair venous return.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":56,"auditFlag":false},{"id":"PDF1-057","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 6","sourcePage":6,"sourceNumber":"57","difficulty":"mixed","topic":"Ventilator waveforms & troubleshooting","question":"A ventilated patient's ETCO₂ is 20 mmHg, while an arterial blood gas shows PaCO₂ 40 mmHg. This large PaCO₂-ETCO₂ difference suggests:","options":["Increased dead space ventilation (e.g., pulmonary embolus).","Equipment malfunction of the CO₂ analyzer.","The patient is hyperventilating.","A large intrapulmonary shunt."],"correct":0,"explanation":"Increased dead space widens the arterial–end-tidal CO₂ difference.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":57,"auditFlag":false},{"id":"PDF1-058","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 6","sourcePage":6,"sourceNumber":"58","difficulty":"mixed","topic":"Ventilator waveforms & troubleshooting","question":"A decelerating (ramp) inspiratory flow pattern (vs. square flow) typically:","options":["Lowers peak airway pressure and improves gas distribution.","Raises peak airway pressure compared to square wave.","Shortens expiratory time automatically.","Is used only in volume control modes."],"correct":0,"explanation":"Decelerating flow often lowers peak pressure and improves distribution.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":58,"auditFlag":false},{"id":"PDF1-059","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 6","sourcePage":6,"sourceNumber":"59","difficulty":"mixed","topic":"Ventilator waveforms & troubleshooting","question":"Normally, end-tidal CO₂ (ETCO₂) is about 4-5 mmHg lower than PaCO₂. If a patient's ETCO₂ is 35 mmHg, a typical arterial PaCO₂ would be about:","options":["40 mmHg.","25 mmHg.","35 mmHg.","50 mmHg."],"correct":0,"explanation":"Estimated PaCO₂≈EtCO₂+5≈40 mmHg.","answerOrigin":"marked in source","calculation":true,"sourceFile":"Mock exam preparation .pdf","originQuestion":59,"auditFlag":false},{"id":"PDF1-060","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 6","sourcePage":6,"sourceNumber":"60","difficulty":"mixed","topic":"Ventilator waveforms & troubleshooting","question":"Plateau pressure on the ventilator predominantly reflects:","options":["Lung compliance (elastic resistance of the lungs).","Airway resistance.","Patient effort.","The presence of auto-PEEP."],"correct":0,"explanation":"In passive ventilation with zero flow, plateau pressure reflects elastic distending pressure, although auto-PEEP and chest wall affect its interpretation.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":60,"auditFlag":false},{"id":"PDF1-061","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 6","sourcePage":6,"sourceNumber":"61","difficulty":"mixed","topic":"Ventilator waveforms & troubleshooting","question":"A capnograph waveform with a slow upslope and lack of a plateau (\"shark fin\" shape) most likely indicates:","options":["Bronchospasm (obstructive airflow, as in asthma/COPD).","Normal exhalation.","A misplaced endotracheal tube.","Hypoventilation."],"correct":0,"explanation":"Obstruction slows expiratory CO₂ washout, giving a characteristic sloped capnogram.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":61,"auditFlag":false},{"id":"PDF1-062","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 5","sourcePage":5,"sourceNumber":"62","difficulty":"mixed","topic":"Ventilator waveforms & troubleshooting","question":"A sudden drop of the end-tidal CO₂ reading to near zero is most consistent with:","options":["Ventilator circuit disconnection or accidental extubation.","Severe bronchospasm.","Oversedation of the patient.","Onset of metabolic acidosis."],"correct":0,"explanation":"Sudden waveform loss requires immediate airway/circuit evaluation.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":62,"auditFlag":false},{"id":"PDF1-063","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 5","sourcePage":5,"sourceNumber":"63","difficulty":"mixed","topic":"Ventilator waveforms & troubleshooting","question":"Ventilator alarm limits (e.g., tidal volume, minute ventilation) are typically set:","options":["~10–20% above and below the target values.","At exactly the prescribed values (no margin).","Only for high pressure, not low volume.","As loosely as possible to avoid alarming."],"correct":0,"explanation":"Alarm thresholds are commonly set around expected values, adjusted to clinical need.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":63,"auditFlag":false},{"id":"PDF1-064","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 5","sourcePage":5,"sourceNumber":"64","difficulty":"mixed","topic":"Ventilator waveforms & troubleshooting","question":"Intrinsic PEEP (auto-PEEP) in a ventilated patient can be measured by performing a(n):","options":["End-expiratory pause (expiratory hold) maneuver.","End-inspiratory pause maneuver.","Sputum culture from the endotracheal tube.","Inspiratory capacity test."],"correct":0,"explanation":"A passive expiratory hold can estimate total PEEP; subtract set PEEP to find intrinsic PEEP.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":64,"auditFlag":false},{"id":"PDF1-065","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 5","sourcePage":5,"sourceNumber":"65","difficulty":"mixed","topic":"ABG & acid–base analysis","question":"Type 1 respiratory failure is defined by:","options":["Elevated PaCO₂ with elevated HCO₃⁻.","PaO₂ < 60 mmHg (hypoxemia) with normal or low PaCO₂.","PaO₂ < 80 mmHg on room air.","PaCO₂ > 50 mmHg with pH > 7.45."],"correct":1,"explanation":"Type 1 respiratory failure is hypoxaemic without primary hypercapnia.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":65,"auditFlag":false},{"id":"PDF1-066","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 5","sourcePage":5,"sourceNumber":"66","difficulty":"mixed","topic":"ABG & acid–base analysis","question":"ABG: pH 7.25, PaCO₂ 60 mmHg, HCO₃⁻ 26 mEq/L. This indicates:","options":["Acute (uncompensated) respiratory acidosis.","Metabolic acidosis.","Mixed respiratory and metabolic acidosis.","Chronic respiratory acidosis (compensated)."],"correct":0,"explanation":"Acidemia with elevated PaCO₂ and near-normal bicarbonate supports acute respiratory acidosis.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":66,"auditFlag":false},{"id":"PDF1-067","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 5","sourcePage":5,"sourceNumber":"67","difficulty":"mixed","topic":"ABG & acid–base analysis","question":"ABG: pH 7.36, PaCO₂ 58 mmHg, HCO₃⁻ 32 mEq/L. This indicates:","options":["Chronic (compensated) respiratory acidosis.","Metabolic alkalosis.","Acute respiratory acidosis.","Combined respiratory acidosis and metabolic alkalosis."],"correct":0,"explanation":"Near-normal pH with hypercapnia and elevated bicarbonate is consistent with renal compensation for chronic respiratory acidosis.","answerOrigin":"verified against course materials","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":67,"auditFlag":false},{"id":"PDF1-068","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 5","sourcePage":5,"sourceNumber":"68","difficulty":"mixed","topic":"ABG & acid–base analysis","question":"ABG: pH 7.10, PaCO₂ 20 mmHg, HCO₃⁻ 6 mEq/L. This pattern is most consistent with:","options":["A high anion gap metabolic acidosis with respiratory alkalosis (e.g., DKA with Kussmaul breathing).","Primary respiratory alkalosis.","Metabolic alkalosis with respiratory compensation.","Normal acid-base status."],"correct":0,"explanation":"Severe metabolic acidosis with reduced PaCO₂ as compensation. The anion gap cannot be confirmed from these values alone; the source calls it high anion gap.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":68,"auditFlag":true,"auditNote":"High anion gap cannot be inferred from ABG without serum electrolyte values."},{"id":"PDF1-069","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 5","sourcePage":5,"sourceNumber":"69","difficulty":"mixed","topic":"ABG & acid–base analysis","question":"Which of the following is a cause of a high anion gap metabolic acidosis?","options":["Diabetic ketoacidosis.","Diarrhea.","Renal tubular acidosis.","Hyperchloremia from NS IV fluids."],"correct":0,"explanation":"DKA causes elevated unmeasured ketoacids.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":69,"auditFlag":false},{"id":"PDF1-070","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 4","sourcePage":4,"sourceNumber":"70","difficulty":"mixed","topic":"ABG & acid–base analysis","question":"ABG: pH 7.52, PaCO₂ 28 mmHg, HCO₃⁻ 24 mEq/L. This indicates:","options":["Acute respiratory alkalosis.","Chronic respiratory alkalosis with compensation.","Metabolic alkalosis.","Combined metabolic and respiratory alkalosis."],"correct":0,"explanation":"Alkalemia with reduced CO₂ and normal bicarbonate supports acute respiratory alkalosis.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":70,"auditFlag":false},{"id":"PDF1-071","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 4","sourcePage":4,"sourceNumber":"71","difficulty":"mixed","topic":"ABG & acid–base analysis","question":"ABG: pH 7.55, PaCO₂ 50 mmHg, HCO₃⁻ 40 mEq/L. This pattern is most consistent with:","options":["Metabolic alkalosis with respiratory compensation.","Respiratory acidosis with metabolic alkalosis.","Chronic respiratory acidosis.","Acute respiratory alkalosis."],"correct":0,"explanation":"High bicarbonate causes alkalemia, and raised PaCO₂ is consistent with compensatory hypoventilation.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":71,"auditFlag":false},{"id":"PDF1-072","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 4","sourcePage":4,"sourceNumber":"72","difficulty":"mixed","topic":"ABG & acid–base analysis","question":"Which arterial blood gas parameter primarily reflects a patient's ventilatory status?","options":["PaCO₂.","PaO₂.","HCO₃⁻.","Base excess."],"correct":0,"explanation":"PaCO₂ reflects effective alveolar ventilation.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":72,"auditFlag":false},{"id":"PDF1-073","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 4","sourcePage":4,"sourceNumber":"73","difficulty":"mixed","topic":"Medical gases & humidification","question":"A non-rebreather mask with reservoir (at 15 L/min O₂ flow) can deliver an FiO₂ of approximately:","options":["0.80–1.00 (80–100%).","0.50 (50%).","0.21 (21%).","0.40 (40%)."],"correct":0,"explanation":"A well-fitting reservoir mask can deliver a high FiO₂; actual FiO₂ depends on seal and ventilation.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":73,"auditFlag":false},{"id":"PDF1-074","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 4","sourcePage":4,"sourceNumber":"74","difficulty":"mixed","topic":"Medical gases & humidification","question":"High-Flow Nasal Cannula (HFNC) oxygen systems can deliver flow rates up to approximately:","options":["60 L/min.","6 L/min.","120 L/min.","15 L/min."],"correct":0,"explanation":"Typical adult high-flow nasal oxygen devices deliver up to roughly 60 L/min.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":74,"auditFlag":false},{"id":"PDF1-075","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 4","sourcePage":4,"sourceNumber":"75","difficulty":"mixed","topic":"Medical gases & humidification","question":"Inhaled nitric oxide (iNO) therapy in ARDS:","options":["Improves oxygenation temporarily but has not been shown to improve survival.","Causes systemic vasodilation to improve blood pressure.","Significantly reduces ARDS mortality.","Is primarily used to treat left ventricular failure."],"correct":0,"explanation":"iNO may temporarily improve oxygenation but does not routinely improve mortality.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":75,"auditFlag":false},{"id":"PDF1-076","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 4","sourcePage":4,"sourceNumber":"76","difficulty":"mixed","topic":"Medical gases & humidification","question":"If a patient remains hypoxemic (SpO₂ < 90%) despite 100% O₂ via non-rebreather mask, the next step is to:","options":["Intubate and initiate mechanical ventilation (with PEEP).","Tolerate the saturation – 100% O₂ is maximal.","Try a Venturi mask at 50%.","Add a second oxygen reservoir in line."],"correct":0,"explanation":"Persistent severe hypoxaemia requires urgent reassessment and escalation of respiratory support.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":76,"auditFlag":false},{"id":"PDF1-077","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 4","sourcePage":4,"sourceNumber":"77","difficulty":"mixed","topic":"Medical gases & humidification","question":"The wall oxygen outlets in hospitals generally deliver gas at approximately:","options":["50–60 psi (≈ 4 bar).","1 atm (0 psi gauge).","5 psi.","2000 psi."],"correct":0,"explanation":"Hospital oxygen pipeline operating pressure is typically around 4 bar or 50–60 psi.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":77,"auditFlag":false},{"id":"PDF1-078","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 3","sourcePage":3,"sourceNumber":"78","difficulty":"mixed","topic":"Medical gases & humidification","question":"A full \"E\" cylinder of oxygen contains about:","options":["660 L of O₂.","2000 L.","50 L.","100 L."],"correct":0,"explanation":"A typical full E-cylinder contains about 660 L of gaseous oxygen (depending on jurisdiction and specifications).","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":78,"auditFlag":false},{"id":"PDF1-079","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 3","sourcePage":3,"sourceNumber":"79","difficulty":"mixed","topic":"Medical gases & humidification","question":"Air fully saturated at body temperature (37°C) holds about how much water vapor?","options":["44 mg H₂O per liter of air.","100 mg/L.","10 mg/L.","4 mg/L."],"correct":0,"explanation":"100% relative humidity at 37°C corresponds to 44 mg H₂O/L.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":79,"auditFlag":false},{"id":"PDF1-080","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 3","sourcePage":3,"sourceNumber":"80","difficulty":"mixed","topic":"Medical gases & humidification","question":"Heat Moisture Exchangers (HMEs) used on ventilator circuits:","options":["Increase dead space and can become clogged by secretions.","Actively heat and humidify gas to body temperature.","Are ideal for patients with thick, copious secretions.","Reduce airway resistance compared to no HME."],"correct":0,"explanation":"HMEs are passive humidifiers and can add dead space and resistance, especially when secretions obstruct them.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":80,"auditFlag":false},{"id":"PDF1-081","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 3","sourcePage":3,"sourceNumber":"81","difficulty":"mixed","topic":"NIV, HFNC & infection prevention","question":"Non-invasive ventilation (e.g., BiPAP) is contraindicated in:","options":["Patients who cannot protect their airway (e.g., GCS < 8, excessive secretions).","COPD exacerbation with hypercapnia.","Acute cardiogenic pulmonary edema.","Obesity hypoventilation syndrome."],"correct":0,"explanation":"Inability to protect the airway is a major contraindication to NIV.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":81,"auditFlag":false},{"id":"PDF1-082","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 3","sourcePage":3,"sourceNumber":"82","difficulty":"mixed","topic":"NIV, HFNC & infection prevention","question":"High-Flow Nasal Cannula (HFNC) helps CO₂ elimination by:","options":["Flushing out anatomical dead space in the upper airway.","Providing higher ventilatory pressures.","Directly removing CO₂ from the blood.","Increasing metabolic rate."],"correct":0,"explanation":"High-flow gas washes exhaled CO₂ out of upper-airway anatomical dead space.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":82,"auditFlag":false},{"id":"PDF1-083","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 3","sourcePage":3,"sourceNumber":"83","difficulty":"mixed","topic":"NIV, HFNC & infection prevention","question":"The maximum duration for each endotracheal suctioning attempt should be approximately:","options":["10–15 seconds.","30 seconds.","1–2 seconds.","As long as needed if secretions persist."],"correct":0,"explanation":"Limit suction passes to about 10–15 seconds to reduce desaturation and trauma.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":83,"auditFlag":false},{"id":"PDF1-084","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 3","sourcePage":3,"sourceNumber":"84","difficulty":"mixed","topic":"NIV, HFNC & infection prevention","question":"Prolonged exposure to FiO₂ 1.0 (100% O₂) can cause:","options":["Oxygen toxicity (e.g., diffuse lung injury, absorption atelectasis).","CO₂ retention in healthy lungs.","Bronchospasm in asthmatics.","Methemoglobinemia."],"correct":0,"explanation":"Prolonged high inspired oxygen can cause absorption atelectasis and oxygen toxicity.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":84,"auditFlag":false},{"id":"PDF1-085","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 3","sourcePage":3,"sourceNumber":"85","difficulty":"mixed","topic":"NIV, HFNC & infection prevention","question":"A key measure to prevent ventilator-associated pneumonia is:","options":["Elevating the head of the bed ~30–45°.","Deep sedation of ventilated patients.","Changing ventilator circuits daily.","Giving prophylactic antibiotics."],"correct":0,"explanation":"Head-of-bed elevation is a standard VAP prevention measure when appropriate.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":85,"auditFlag":false},{"id":"PDF1-086","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 2","sourcePage":2,"sourceNumber":"86","difficulty":"mixed","topic":"Clinical ventilation & weaning","question":"Chest drains for pneumothorax are often connected to wall suction. A typical suction level for an adult chest tube water-seal drainage system is:","options":["-20 cm H₂O.","-50 cm H₂O.","-5 cm H₂O.","No suction (gravity drainage only)."],"correct":0,"explanation":"When suction is prescribed, a commonly used chest-drain suction level is −20 cm H₂O; specific orders/devices may differ.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":86,"auditFlag":false},{"id":"PDF1-087","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 2","sourcePage":2,"sourceNumber":"87","difficulty":"mixed","topic":"Clinical ventilation & weaning","question":"A Venturi mask is useful because it:","options":["Delivers a fixed, precise FiO₂ by air entrainment.","Provides positive pressure ventilation.","Passively humidifies oxygen.","Can deliver 100% O₂ without intubation."],"correct":0,"explanation":"Venturi systems entrain air in a calibrated ratio for controlled FiO₂.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":87,"auditFlag":false},{"id":"PDF1-088","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 2","sourcePage":2,"sourceNumber":"88","difficulty":"mixed","topic":"Clinical ventilation & weaning","question":"Which index is commonly used to predict success in weaning from mechanical ventilation?","options":["APACHE II score.","Rapid Shallow Breathing Index (RSBI = f/VT).","Serum bicarbonate level.","Glasgow Coma Scale."],"correct":1,"explanation":"RSBI relates frequency to tidal volume and is one aid to weaning assessment.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":88,"auditFlag":false},{"id":"PDF1-089","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 2","sourcePage":2,"sourceNumber":"89","difficulty":"mixed","topic":"Clinical ventilation & weaning","question":"A patient's Negative Inspiratory Force (NIF, or MIP) is -10 cm H₂O. This suggests:","options":["Weak inspiratory muscles and a high risk of weaning failure.","Normal inspiratory muscle strength.","The patient is ready for extubation.","The test was invalid (normal NIF is -10)."],"correct":0,"explanation":"Less-negative NIF suggests weak respiratory muscles and potentially difficult liberation.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":89,"auditFlag":false},{"id":"PDF1-090","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 2","sourcePage":2,"sourceNumber":"90","difficulty":"mixed","topic":"Clinical ventilation & weaning","question":"An appropriate lung-protective ventilation strategy for ARDS is:","options":["Low tidal volume (~6 mL/kg) and permissive hypercapnia.","Routine inhaled nitric oxide to improve survival.","Minimal PEEP (≤ 5 cm H₂O) to avoid barotrauma.","High tidal volume to ensure PaCO₂ normalization."],"correct":0,"explanation":"ARDS lung protection centres on low VT (predicted body weight) and limiting lung stress.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":90,"auditFlag":false},{"id":"PDF1-091","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 2","sourcePage":2,"sourceNumber":"91","difficulty":"mixed","topic":"Clinical ventilation & weaning","question":"In mechanical ventilation of a severe COPD exacerbation, a key strategy is to:","options":["Use high respiratory rates to blow off CO₂.","Avoid any PEEP to prevent barotrauma.","Allow prolonged expiratory time (e.g., low rate, I:E ≈ 1:3–4) to prevent air trapping.","Target an SpO₂ of 100% with high FiO₂."],"correct":2,"explanation":"Long expiratory time minimises dynamic hyperinflation in airflow obstruction.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":91,"auditFlag":false},{"id":"PDF1-092","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 2","sourcePage":2,"sourceNumber":"92","difficulty":"mixed","topic":"Clinical ventilation & weaning","question":"A 30-year-old C5 spinal cord injury patient is in respiratory distress with copious secretions and a PaCO₂ of 61 mmHg on 100% NRB. The best management is to:","options":["Begin BiPAP noninvasive ventilation.","Intubate and start mechanical ventilation (protect airway and support ventilation).","Continue the NRB and await improvement.","Perform nasopharyngeal suctioning only and wait."],"correct":1,"explanation":"Neuromuscular weakness, secretion burden and hypercapnia may require invasive ventilatory support.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":92,"auditFlag":false},{"id":"PDF1-093","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 2","sourcePage":2,"sourceNumber":"93","difficulty":"mixed","topic":"Clinical ventilation & weaning","question":"In a patient with ARDS, placing the patient prone typically:","options":["Is contraindicated in hypoxemic respiratory failure.","Improves oxygenation by enhancing ventilation-perfusion matching.","Worsens oxygenation by compressing the chest.","Only aids in secretion clearance, not gas exchange."],"correct":1,"explanation":"Proning improves regional recruitment and V/Q balance.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":93,"auditFlag":false},{"id":"PDF1-094","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 1","sourcePage":1,"sourceNumber":"94","difficulty":"mixed","topic":"Clinical ventilation & weaning","question":"Permissive hypercapnia (allowing PaCO₂ to rise) is relatively contraindicated in:","options":["Patients with elevated intracranial pressure (risk of cerebral vasodilation).","Status asthmaticus.","ARDS patients with refractory hypoxemia.","COPD exacerbation with acidosis."],"correct":0,"explanation":"High PaCO₂ can cause cerebral vasodilation and worsen intracranial pressure.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":94,"auditFlag":false},{"id":"PDF1-095","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 1","sourcePage":1,"sourceNumber":"95","difficulty":"mixed","topic":"Clinical ventilation & weaning","question":"It is generally recommended to keep plateau (alveolar) pressure below 30 cm H₂O in ventilated patients to:","options":["Reduce the risk of barotrauma (alveolar overdistension).","Avoid auto-PEEP.","Ensure adequate tidal volumes.","Prevent respiratory alkalosis."],"correct":0,"explanation":"A plateau pressure below ~30 cm H₂O is a key lung-protective target.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":95,"auditFlag":false},{"id":"PDF1-096","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 1","sourcePage":1,"sourceNumber":"96","difficulty":"mixed","topic":"Clinical ventilation & weaning","question":"A spontaneous breathing trial (e.g., T-piece trial) is used to:","options":["Test if a patient can breathe adequately without ventilator assistance before extubation.","Strengthen respiratory muscles by alternating mandatory breaths.","Provide full rest to the patient on the ventilator.","Hyperoxygenate a patient prior to suctioning."],"correct":0,"explanation":"SBTs assess readiness for spontaneous breathing off substantial ventilator assistance.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":96,"auditFlag":false},{"id":"PDF1-097","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 1","sourcePage":1,"sourceNumber":"97","difficulty":"mixed","topic":"Clinical ventilation & weaning","question":"Excessively high levels of PEEP can cause:","options":["Barotrauma (e.g., pneumothorax).","Improvement in cardiac output.","Metabolic alkalosis.","Airway closure at end-inspiration."],"correct":0,"explanation":"Excessive lung distension from high PEEP increases barotrauma risk.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":97,"auditFlag":false},{"id":"PDF1-098","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 1","sourcePage":1,"sourceNumber":"98","difficulty":"mixed","topic":"Clinical ventilation & weaning","question":"Which of the following is TRUE regarding COPD?","options":["COPD patients typically have FEV₁/FVC > 0.7.","The airflow limitation in COPD is not fully reversible with bronchodilators.","COPD primarily affects young, non-smokers.","Mood disorders are uncommon in COPD."],"correct":1,"explanation":"COPD involves persistent airflow obstruction not fully reversible with bronchodilators.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":98,"auditFlag":false},{"id":"PDF1-099","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 1","sourcePage":1,"sourceNumber":"99","difficulty":"mixed","topic":"Clinical ventilation & weaning","question":"Some COVID-19 patients exhibit \"happy hypoxia\" – severe hypoxemia without proportional distress. The primary mechanism is:","options":["Significant V/Q mismatch (shunt) with relatively preserved CO₂ elimination.","Methemoglobinemia.","Decreased oxygen consumption.","Psychogenic hyperventilation."],"correct":0,"explanation":"Marked V/Q disturbance may cause hypoxaemia even if the patient's ventilatory sensation is relatively preserved.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":99,"auditFlag":false},{"id":"PDF1-100","examId":"mock1","source":"Mock exam preparation .pdf — PDF page 1","sourcePage":1,"sourceNumber":"100","difficulty":"mixed","topic":"Clinical ventilation & weaning","question":"In acute traumatic brain injury, brief hyperventilation helps lower intracranial pressure because:","options":["It raises mean arterial pressure.","It increases CSF drainage.","High PaO₂ directly reduces cerebral edema.","Low PaCO₂ causes cerebral vasoconstriction, reducing cerebral blood volume."],"correct":3,"explanation":"Hypocapnia causes cerebral arteriolar vasoconstriction and may briefly lower cerebral blood volume.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":100,"auditFlag":false},{"id":"PDF2-001","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 43","sourcePage":43,"sourceNumber":"1","difficulty":"mixed","topic":"Gas laws & physiology","question":"What is the approximate partial pressure of oxygen in atmospheric air at sea level?","options":["760 mmHg","21 mmHg","99 mmHg","150 mmHg"],"correct":3,"explanation":"Dry air oxygen partial pressure ≈0.21×760=160 mmHg; 150 mmHg is the closest answer provided.","answerOrigin":"marked in source","calculation":true,"sourceFile":"Mock exam preparation .pdf","originQuestion":1,"auditFlag":true,"auditNote":"Dry atmospheric O2 at sea level is ~160 mmHg; closest listed option is 150."},{"id":"PDF2-002","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 43","sourcePage":43,"sourceNumber":"2","difficulty":"mixed","topic":"Gas laws & physiology","question":"In the oxygen cascade, what is the typical partial pressure of oxygen (PO₂) at the mitochondrial level?","options":["150 mmHg","99 mmHg","33 mmHg","5 mmHg"],"correct":3,"explanation":"Mitochondrial PO₂ is low, often estimated around a few mmHg.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":2,"auditFlag":false},{"id":"PDF2-003","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 43","sourcePage":43,"sourceNumber":"3","difficulty":"mixed","topic":"Gas laws & physiology","question":"Dalton's Law states that:","options":["Pressure and volume of a gas are inversely proportional (Boyle's Law)","The total pressure of a gas mixture equals the sum of the partial pressures of its components","Gas bubbles in blood will not dissolve due to high venous pressures","Gas movement is directly proportional to temperature (Charles's Law)"],"correct":1,"explanation":"Dalton's law relates total pressure to the sum of partial pressures.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":3,"auditFlag":false},{"id":"PDF2-004","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 43","sourcePage":43,"sourceNumber":"4","difficulty":"mixed","topic":"Gas laws & physiology","question":"According to Boyle's Law, what is the relationship between the pressure and volume of a gas (at constant temperature)?","options":["Directly proportional","Inversely proportional","Unrelated","Exponentially related"],"correct":1,"explanation":"At constant temperature, P×V stays constant.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":4,"auditFlag":false},{"id":"PDF2-005","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 43","sourcePage":43,"sourceNumber":"5","difficulty":"mixed","topic":"Gas laws & physiology","question":"On the oxygen–hemoglobin dissociation curve, a PaO₂ of 60 mmHg corresponds to approximately what hemoglobin saturation (SaO₂), defining the threshold of respiratory failure?","options":["50%","75%","90%","100%"],"correct":2,"explanation":"At PaO₂≈60 mmHg, SaO₂≈90%.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":5,"auditFlag":false},{"id":"PDF2-006","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 43","sourcePage":43,"sourceNumber":"6","difficulty":"mixed","topic":"Gas laws & physiology","question":"What is the shape of the normal oxygen–hemoglobin dissociation curve?","options":["Linear","Exponential","Sigmoid (S-shaped)","Parabolic"],"correct":2,"explanation":"Cooperative oxygen binding generates a sigmoidal curve.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":6,"auditFlag":false},{"id":"PDF2-007","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 43","sourcePage":43,"sourceNumber":"7","difficulty":"mixed","topic":"Gas laws & physiology","question":"Assuming normal hemoglobin (15 g/dL) and 100% saturation, roughly how much oxygen is carried in 100 mL of blood (oxygen content)?","options":["~4 mL O₂","~10 mL O₂","~20 mL O₂","~25 mL O₂"],"correct":2,"explanation":"1.34×15=20.1 mL/dL.","answerOrigin":"marked in source","calculation":true,"sourceFile":"Mock exam preparation .pdf","originQuestion":7,"auditFlag":false},{"id":"PDF2-008","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 42","sourcePage":42,"sourceNumber":"8","difficulty":"mixed","topic":"Gas laws & physiology","question":"Which formula represents the alveolar–arterial oxygen gradient (A–a DO₂)?","options":["PaO₂ − PAO₂","PAO₂ − PaO₂","FiO₂ × (Patm − PH₂O)","VCO₂ / VA"],"correct":1,"explanation":"A–a oxygen gradient = calculated alveolar PO₂ minus measured arterial PO₂.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":8,"auditFlag":false},{"id":"PDF2-009","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 42","sourcePage":42,"sourceNumber":"9","difficulty":"mixed","topic":"Gas laws & physiology","question":"A higher than normal A–a oxygen gradient generally indicates:","options":["Better-than-normal lung function","Normal age-related changes","Worse lung function (V/Q mismatch or shunting)","Increased CO₂ production"],"correct":2,"explanation":"A widened A–a gradient suggests an oxygen transfer abnormality.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":9,"auditFlag":false},{"id":"PDF2-010","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 42","sourcePage":42,"sourceNumber":"10","difficulty":"mixed","topic":"Gas laws & physiology","question":"What is the approximate rate of CO₂ production in a resting adult (in mL of CO₂ per kg per minute)?","options":["1–2 mL/kg/min","3–4 mL/kg/min","5–6 mL/kg/min","7–8 mL/kg/min"],"correct":1,"explanation":"Typical resting CO₂ production is on the order of ~3 mL/kg/min.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":10,"auditFlag":false},{"id":"PDF2-011","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 42","sourcePage":42,"sourceNumber":"11","difficulty":"mixed","topic":"Gas laws & physiology","question":"Which formula is often used to estimate the PaCO₂ in terms of CO₂ production and alveolar ventilation (useful in ventilator management)?","options":["PaCO₂ = VCO₂ × VA","PaCO₂ = VA / VCO₂","PaCO₂ = VCO₂ / VA","PaCO₂ = FiO₂ / VA"],"correct":2,"explanation":"PaCO₂ is proportional to VCO₂/VA; a dimensional conversion factor is omitted in the options.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":11,"auditFlag":false},{"id":"PDF2-012","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 42","sourcePage":42,"sourceNumber":"12","difficulty":"mixed","topic":"Gas laws & physiology","question":"What is the normal anatomical dead space volume in an adult (approximately equal to body weight in pounds)?","options":["~50 mL","~100 mL","~150 mL","~200 mL"],"correct":2,"explanation":"Anatomical dead space is ~2 mL/kg, around 150 mL in a typical adult.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":12,"auditFlag":false},{"id":"PDF2-013","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 42","sourcePage":42,"sourceNumber":"13","difficulty":"mixed","topic":"Gas laws & physiology","question":"Increased dead space ventilation primarily leads to which blood gas change?","options":["Hypoxemia (low O₂)","Hypocapnia (low CO₂)","Hypercapnia (high CO₂)","Metabolic acidosis"],"correct":2,"explanation":"At the same minute ventilation, more dead space reduces alveolar ventilation and raises PaCO₂.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":13,"auditFlag":false},{"id":"PDF2-014","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 42","sourcePage":42,"sourceNumber":"14","difficulty":"mixed","topic":"Gas laws & physiology","question":"What is the general shape of the CO₂ dissociation curve (CO₂–content relationship in blood)?","options":["Sigmoid (S-shaped)","Parabolic","Exponential","Relatively linear"],"correct":3,"explanation":"Blood CO₂ content varies relatively linearly with PCO₂ over the physiological range.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":14,"auditFlag":false},{"id":"PDF2-015","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 34","sourcePage":34,"sourceNumber":"15","difficulty":"mixed","topic":"Lung volumes & mechanics","question":"Which of the following is a primary function of Functional Residual Capacity (FRC)?","options":["Increase the work of breathing","Act as an oxygen reserve and buffer for the lungs","Maximize V/Q mismatch","Store residual volume after forced expiration"],"correct":1,"explanation":"FRC acts as an oxygen reservoir between breaths.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":15,"auditFlag":false},{"id":"PDF2-016","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 34","sourcePage":34,"sourceNumber":"16","difficulty":"mixed","topic":"Lung volumes & mechanics","question":"Which of the following conditions is known to decrease FRC (Functional Residual Capacity)?","options":["Standing upright","Emphysema","Obesity","Increased height"],"correct":2,"explanation":"Abdominal load and reduced chest wall compliance lower FRC in obesity.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":16,"auditFlag":false},{"id":"PDF2-017","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 34","sourcePage":34,"sourceNumber":"17","difficulty":"mixed","topic":"Lung volumes & mechanics","question":"If Closing Capacity (CC) rises above FRC in a patient (i.e. CC > FRC), what is the likely consequence during normal breathing?","options":["Improved oxygenation","Premature airway closure leading to hypoxemia","Reduced work of breathing","Decreased pulmonary vascular resistance"],"correct":1,"explanation":"When CC exceeds FRC, dependent airway closure causes V/Q mismatch.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":17,"auditFlag":false},{"id":"PDF2-018","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 34","sourcePage":34,"sourceNumber":"18","difficulty":"mixed","topic":"Lung volumes & mechanics","question":"During spontaneous breathing, what is the typical range of intrapleural (pleural) pressure on inspiration?","options":["Approximately +2 to +6 cm H₂O","Approximately −2 to −6 cm H₂O","0 cm H₂O (atmospheric)","It varies widely with lung compliance"],"correct":1,"explanation":"Pleural pressure becomes more negative with spontaneous inspiration.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":18,"auditFlag":false},{"id":"PDF2-019","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 34","sourcePage":34,"sourceNumber":"19","difficulty":"mixed","topic":"Lung volumes & mechanics","question":"What is the target level of humidification in the alveoli (100% relative humidity at 37 °C)?","options":["~28 mg/L of water","~33 mg/L of water","~44 mg/L of water","~60 mg/L of water"],"correct":2,"explanation":"At 37°C, saturated gas contains about 44 mg/L water.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":19,"auditFlag":false},{"id":"PDF2-020","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 34","sourcePage":34,"sourceNumber":"20","difficulty":"mixed","topic":"Airway assessment & weaning","question":"What is the correct patient head/neck position for endotracheal intubation?","options":["Neck flexed forward, chin down (\"tuck\" position)","Head elevated and neck flexed, with atlanto-occipital extension (\"sniffing\" position)","Neck extended and head flat on table","Trendelenburg position (head down)"],"correct":1,"explanation":"The sniffing position promotes alignment for direct laryngoscopy.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":20,"auditFlag":false},{"id":"PDF2-021","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 34","sourcePage":34,"sourceNumber":"21","difficulty":"mixed","topic":"Airway assessment & weaning","question":"In the Mallampati classification for airway assessment, what does Class I indicate?","options":["Full visibility of the soft palate, fauces, uvula, and pillars","Soft palate and base of uvula are visible","Only the soft palate is visible (no uvula)","No structures are visible (only hard palate seen)"],"correct":0,"explanation":"Mallampati class I shows the soft palate, fauces, uvula and pillars.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":21,"auditFlag":false},{"id":"PDF2-022","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 33","sourcePage":33,"sourceNumber":"22","difficulty":"mixed","topic":"Airway assessment & weaning","question":"Which of the following is not part of a typical Rapid Sequence Induction (RSI) protocol for intubation?","options":["Pre-oxygenation with 100% O₂","Administering a beta-blocker to attenuate sympathetic response","Applying cricoid pressure (Sellick's maneuver)","Using a fast-acting IV induction agent and neuromuscular blocker"],"correct":1,"explanation":"Beta-blockers are not a standard RSI step; cricoid pressure is historically taught and now selectively used.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":22,"auditFlag":false},{"id":"PDF2-023","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 33","sourcePage":33,"sourceNumber":"23","difficulty":"mixed","topic":"Airway assessment & weaning","question":"On chest X-ray, where should the tip of a properly placed endotracheal tube be located?","options":["At the level of the carina","A few centimeters above the carina (around the 4th thoracic vertebra)","In the right mainstem bronchus","At the level of the vocal cords in the larynx"],"correct":1,"explanation":"An ETT tip should be proximal to the carina, usually a few cm above it.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":23,"auditFlag":false},{"id":"PDF2-024","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 33","sourcePage":33,"sourceNumber":"24","difficulty":"mixed","topic":"Airway assessment & weaning","question":"If an endotracheal tube is advanced too far and enters the right main bronchus, what is the most likely outcome?","options":["Right lung collapse","Left lung collapse","Bilateral tension pneumothoraces","Tracheal perforation"],"correct":1,"explanation":"Right mainstem intubation can exclude ventilation of the left lung.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":24,"auditFlag":false},{"id":"PDF2-025","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 33","sourcePage":33,"sourceNumber":"25","difficulty":"mixed","topic":"Airway assessment & weaning","question":"What does the Negative Inspiratory Pressure (NIP) or Maximum Inspiratory Pressure (MIP) test assess in ventilated patients?","options":["Cough strength and peak flow","Upper airway patency","Inspiratory muscle strength (ability to take a deep breath) for weaning readiness","Adequacy of pain control for breathing efforts"],"correct":2,"explanation":"NIP/MIP estimates inspiratory muscle strength.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":25,"auditFlag":false},{"id":"PDF2-026","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 33","sourcePage":33,"sourceNumber":"26","difficulty":"mixed","topic":"Airway assessment & weaning","question":"A patient's NIP (MIP) is −8 cm H₂O. What does this finding suggest about the likelihood of successful extubation?","options":["It is above the usual threshold (patient likely can be extubated)","It is weaker than recommended (patient may fail extubation if under −10 cm H₂O)","It indicates excessive inspiratory effort","It suggests the patient is hyperventilating"],"correct":1,"explanation":"−8 cm H₂O is a weak inspiratory force; no single NIP threshold by itself establishes extubation readiness.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":26,"auditFlag":false},{"id":"PDF2-027","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 33","sourcePage":33,"sourceNumber":"27","difficulty":"mixed","topic":"Airway assessment & weaning","question":"How is a NIP/MIP measurement typically obtained on an intubated or tracheostomized patient?","options":["By using the ventilator's built-in sensors during a normal breath","With a dedicated manometer attached to the ETT/trach, isolated from the ventilator","By measuring end-tidal CO₂ changes during inspiratory hold","By calculating from tidal volume and compliance"],"correct":1,"explanation":"Occlusion pressure can be measured using a manometer and an occlusion manoeuvre.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":27,"auditFlag":false},{"id":"PDF2-028","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 33","sourcePage":33,"sourceNumber":"28","difficulty":"mixed","topic":"Airway assessment & weaning","question":"What is a T-piece trial in the context of weaning from mechanical ventilation?","options":["A spontaneous breathing trial where the patient breathes through a T-piece with no ventilatory assist (zero pressure support)","A trial of pressure support ventilation at low pressure (5 cm H₂O)","A period of high-level CPAP used to assess readiness for extubation","Synchronized Intermittent Mandatory Ventilation (SIMV) at a low rate to test spontaneous breathing"],"correct":0,"explanation":"A T-piece trial allows spontaneous breathing without ventilator pressure assistance.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":28,"auditFlag":false},{"id":"PDF2-029","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 15","sourcePage":15,"sourceNumber":"29","difficulty":"mixed","topic":"Ventilator modes & settings","question":"Which of the following is not one of the three basic ventilator modes/types?","options":["Volume Control (VC) ventilation","Pressure Control (PC) ventilation","Synchronized Intermittent Mandatory Ventilation (SIMV)","Spontaneous/Supported breathing (e.g. Pressure Support)"],"correct":2,"explanation":"The source groups the three basic types as VC, PC, and spontaneous/supported modes; SIMV is a breath-sequence strategy.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":29,"auditFlag":false},{"id":"PDF2-030","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 15","sourcePage":15,"sourceNumber":"30","difficulty":"mixed","topic":"Ventilator modes & settings","question":"In Volume Control (VC) ventilation, which parameter is set (controlled) by the operator?","options":["Peak inspiratory pressure","Tidal volume","Inspiratory-to-expiratory (I:E) ratio","Respiratory rate is the only controlled parameter"],"correct":1,"explanation":"VC targets a set tidal volume.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":30,"auditFlag":false},{"id":"PDF2-031","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 15","sourcePage":15,"sourceNumber":"31","difficulty":"mixed","topic":"Ventilator modes & settings","question":"In Pressure Control (PC) ventilation, which of the following is directly set by the operator?","options":["Tidal volume","Inspiratory flow rate","Peak inspiratory pressure (the pressure limit)","Minute ventilation"],"correct":2,"explanation":"PC applies a preset inspiratory pressure; tidal volume depends on mechanics.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":31,"auditFlag":false},{"id":"PDF2-032","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 15","sourcePage":15,"sourceNumber":"32","difficulty":"mixed","topic":"Ventilator modes & settings","question":"Pressure Support (PS) ventilation is always patient-triggered and pressure-limited. How does a pressure-supported breath normally end (cycle off)?","options":["It cycles off after a set time interval","It cycles off after a set tidal volume is reached","It cycles off when inspiratory flow drops to a preset fraction of peak flow (flow-cycled)","It does not cycle off until the patient exhales voluntarily"],"correct":2,"explanation":"PSV typically cycles inspiration off once flow drops to its cycling threshold.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":32,"auditFlag":false},{"id":"PDF2-033","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 15","sourcePage":15,"sourceNumber":"33","difficulty":"mixed","topic":"Ventilator modes & settings","question":"Which patient trigger method for initiating a ventilator breath is generally the most sensitive (requires least patient effort)?","options":["Time triggering","Pressure triggering","Flow triggering","Manual triggering by clinician"],"correct":2,"explanation":"Flow triggering generally reduces patient work compared with older pressure triggering.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":33,"auditFlag":false},{"id":"PDF2-034","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 15","sourcePage":15,"sourceNumber":"34","difficulty":"mixed","topic":"Ventilator modes & settings","question":"On many ICU ventilators, what is the default pressure trigger sensitivity set to?","options":["−1 cm H₂O (drop below PEEP)","−2 cm H₂O","0 cm H₂O (atmospheric)","+2 cm H₂O"],"correct":1,"explanation":"A common pressure-trigger setting is a 1–2 cm H₂O drop below baseline PEEP, though settings vary by ventilator.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":34,"auditFlag":false},{"id":"PDF2-035","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 15","sourcePage":15,"sourceNumber":"35","difficulty":"mixed","topic":"Ventilator modes & settings","question":"Beyond approximately what respiratory rate does increasing the rate yield diminishing returns in CO₂ elimination (due to inadequate expiratory time)?","options":[">10 breaths/min",">15–20 breaths/min",">30 breaths/min",">60 breaths/min"],"correct":1,"explanation":"This source's threshold applies to patients with prolonged expiratory time constants; the clinically meaningful rate varies by disease and ventilator settings.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":35,"auditFlag":true,"auditNote":"Specific RR threshold is not generalizable to all patients."},{"id":"PDF2-036","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 15","sourcePage":15,"sourceNumber":"36","difficulty":"mixed","topic":"Ventilator modes & settings","question":"What is a typical recommended tidal volume (V<sub>T</sub>) setting for lung-protective ventilation in adults?","options":["4–6 mL/kg of ideal body weight","6–8 mL/kg of ideal body weight","10–12 mL/kg of actual body weight","~15 mL/kg (to ensure adequate minute ventilation)"],"correct":1,"explanation":"The source teaches 6–8 mL/kg of ideal weight; ARDS often targets 6 mL/kg predicted body weight.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":36,"auditFlag":false},{"id":"PDF2-037","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 16","sourcePage":16,"sourceNumber":"37","difficulty":"mixed","topic":"Ventilator modes & settings","question":"What is a typical initial Positive End-Expiratory Pressure (PEEP) setting in adult mechanical ventilation?","options":["0 cm H₂O (no PEEP)","3–5 cm H₂O","8–10 cm H₂O",">15 cm H₂O"],"correct":1,"explanation":"Initial PEEP around 5 cm H₂O is common; subsequent titration depends on oxygenation and haemodynamics.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":37,"auditFlag":false},{"id":"PDF2-038","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 16","sourcePage":16,"sourceNumber":"38","difficulty":"mixed","topic":"Ventilator modes & settings","question":"What is a common inspiratory-to-expiratory ratio used for adult patients on mechanical ventilation?","options":["1:1","1:2 (or up to 1:3)","1:4","2:1 (inverse ratio)"],"correct":1,"explanation":"A normal starting I:E is approximately 1:2.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":38,"auditFlag":false},{"id":"PDF2-039","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 16","sourcePage":16,"sourceNumber":"39","difficulty":"mixed","topic":"Ventilator waveforms","question":"In a pressure–time waveform during Volume Control ventilation, what is a typical characteristic?","options":["The airway pressure remains constant during inspiration","The airway pressure varies depending on lung compliance (often showing a sharp peak P<sub>IP</sub>)","The airway pressure rises linearly and then plateaus at a set level","There is no peak inspiratory pressure in volume control mode"],"correct":1,"explanation":"Pressure is dependent on resistance/compliance and flow in VC, unlike targeted pressure in PC.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":39,"auditFlag":false},{"id":"PDF2-040","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 16","sourcePage":16,"sourceNumber":"40","difficulty":"mixed","topic":"Ventilator waveforms","question":"A large difference between peak inspiratory pressure (PIP) and plateau pressure (P<sub>plat</sub>) is indicative of:","options":["High lung compliance","High airway resistance (e.g. due to bronchospasm or secretions)","Patient–ventilator asynchrony","An overestimation error in measurement"],"correct":1,"explanation":"PIP-Pplat approximates resistive pressure during passive constant-flow ventilation.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":40,"auditFlag":false},{"id":"PDF2-041","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 16","sourcePage":16,"sourceNumber":"41","difficulty":"mixed","topic":"Ventilator waveforms","question":"A capnography waveform with a prolonged \"shark fin\" expiratory up-slope (as shown by the CO₂ vs. time curve) is most suggestive of:","options":["Normal lung emptying","Inadequate sampling by the capnometer","Small airway obstruction (e.g. bronchospasm as in COPD/asthma)","Circuit disconnection"],"correct":2,"explanation":"Prolonged expiratory upstroke reflects obstructed emptying.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":41,"auditFlag":false},{"id":"PDF2-042","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 16","sourcePage":16,"sourceNumber":"42","difficulty":"mixed","topic":"Ventilator waveforms","question":"On the pressure–volume (P–V) loop of a ventilator, a very steep slope (low pressure for a given volume) in the initial portion of the loop indicates:","options":["Decreased lung compliance (stiff lungs)","Increased lung compliance (very 'stretchy' lungs)","Overdistension of the lungs at low volumes","Excessive patient effort"],"correct":1,"explanation":"P–V loop slope is ΔV/ΔP, so a steeper slope indicates greater compliance.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":42,"auditFlag":false},{"id":"PDF2-043","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 16","sourcePage":16,"sourceNumber":"43","difficulty":"mixed","topic":"Ventilator waveforms","question":"In ARDS (stiff, non-compliant lungs), the pressure–volume curve would tend to be:","options":["Steeper than normal (shifted upward/left)","Flatter (more horizontal) than normal, requiring higher pressures for volume","The same shape as normal but shifted downward","Characterized by a steeper slope at higher pressures"],"correct":1,"explanation":"Stiff lungs produce less volume per unit pressure.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":43,"auditFlag":false},{"id":"PDF2-044","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 32","sourcePage":32,"sourceNumber":"44","difficulty":"mixed","topic":"Ventilator waveforms","question":"In a ventilator pressure–volume loop, a small clockwise \"loop within the loop\" (a short deviation or inflection) in the otherwise counter-clockwise hysteresis loop typically indicates:","options":["A circuit leak during inspiration","An artifact from the ventilator display","Patient inspiratory effort during assisted ventilation","Overdistension of alveoli at high volume"],"correct":2,"explanation":"An inspiratory-effort distortion can produce a loop within a loop.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":44,"auditFlag":false},{"id":"PDF2-045","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 32","sourcePage":32,"sourceNumber":"45","difficulty":"mixed","topic":"Clinical ventilation","question":"Which statement best describes a challenge in ventilating patients with acute asthma or COPD exacerbation?","options":["They have primarily upper-airway obstruction causing inspiratory stridor","They tend to develop gas trapping due to small-airway obstruction (expiratory wheeze)","They have very non-compliant lungs requiring high pressures (low compliance)","They have reduced respiratory drive leading to hypoventilation"],"correct":1,"explanation":"Obstructive disease prolongs expiration and predisposes to dynamic hyperinflation.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":45,"auditFlag":false},{"id":"PDF2-046","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 32","sourcePage":32,"sourceNumber":"46","difficulty":"mixed","topic":"Clinical ventilation","question":"Which I:E ratio would be appropriate to allow a prolonged expiratory phase for a severe asthmatic on the ventilator?","options":["1:1","1:2","1:4","4:1 (inverse ratio ventilation)"],"correct":2,"explanation":"A 1:4 ratio gives extra expiratory time in severe obstruction.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":46,"auditFlag":false},{"id":"PDF2-047","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 32","sourcePage":32,"sourceNumber":"47","difficulty":"mixed","topic":"Clinical ventilation","question":"In ARDS management, ventilator strategy aims to keep the plateau pressure (P<sub>plat</sub>) below approximately:","options":["20 cm H₂O","30 cm H₂O","40 cm H₂O","50 cm H₂O"],"correct":1,"explanation":"The classic lung-protective ceiling is plateau pressure under 30 cm H₂O.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":47,"auditFlag":false},{"id":"PDF2-048","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 32","sourcePage":32,"sourceNumber":"48","difficulty":"mixed","topic":"Clinical ventilation","question":"Which patient positioning has been shown to improve oxygenation in severe ARDS?","options":["Supine position","Prone position","Trendelenburg position","Lateral decubitus position"],"correct":1,"explanation":"Prone positioning improves V/Q matching and recruitment in severe ARDS.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":48,"auditFlag":false},{"id":"PDF2-049","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 32","sourcePage":32,"sourceNumber":"49","difficulty":"mixed","topic":"Clinical ventilation","question":"Acute cardiogenic pulmonary edema causes hypoxemia primarily by which mechanism?","options":["Increased dead space ventilation","Reduced cardiac output","Intrapulmonary shunting due to fluid-filled alveoli","Diffusion block for O₂ across the alveolar membrane"],"correct":2,"explanation":"Fluid-filled alveoli are perfused but poorly ventilated, producing low V/Q and shunt.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":49,"auditFlag":false},{"id":"PDF2-050","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 31","sourcePage":31,"sourceNumber":"50","difficulty":"mixed","topic":"Clinical ventilation","question":"In a mechanically ventilated patient with lobar lung collapse (atelectasis), an appropriate management step is:","options":["Lower the PEEP to avoid barotrauma","Increase inspiratory flow to reduce inspiratory time","Perform suctioning or bronchoscopy to clear obstruction, and use recruitment maneuvers/PEEP","Lower FiO₂ to prevent oxygen toxicity"],"correct":2,"explanation":"When obstruction causes atelectasis, clear it and consider recruitment according to patient condition.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":50,"auditFlag":false},{"id":"PDF2-051","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 31","sourcePage":31,"sourceNumber":"51","difficulty":"mixed","topic":"Medical gases & oxygen cylinders","question":"At approximately what extreme temperature is medical liquid oxygen stored?","options":["0 °C","−50 °C","−180 °C","−320 °C (absolute zero is −273 °C)"],"correct":2,"explanation":"Liquid oxygen is stored cryogenically at approximately −183 °C at atmospheric pressure.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":51,"auditFlag":false},{"id":"PDF2-052","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 31","sourcePage":31,"sourceNumber":"52","difficulty":"mixed","topic":"Medical gases & oxygen cylinders","question":"What is the standard wall outlet supply pressure for medical gases (e.g. oxygen) in a hospital?","options":["~100 kPa","~410 kPa","~700 kPa","~1 atm (760 mmHg)"],"correct":1,"explanation":"Medical gas pipeline pressure is roughly 400–415 kPa.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":52,"auditFlag":false},{"id":"PDF2-053","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 31","sourcePage":31,"sourceNumber":"53","difficulty":"mixed","topic":"Medical gases & oxygen cylinders","question":"410 kPa is approximately equal to what pressure in psi (pounds per square inch)?","options":["~30 psi","~45 psi","~60 psi","~100 psi"],"correct":2,"explanation":"410/6.895≈59.5 psi, approximately 60 psi.","answerOrigin":"marked in source","calculation":true,"sourceFile":"Mock exam preparation .pdf","originQuestion":53,"auditFlag":false},{"id":"PDF2-054","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 31","sourcePage":31,"sourceNumber":"54","difficulty":"mixed","topic":"Medical gases & oxygen cylinders","question":"What is the Pin Index configuration for an oxygen cylinder?","options":["Pins 1 and 5","Pins 2 and 5","Pins 2 and 4","Pins 4 and 6"],"correct":1,"explanation":"The oxygen pin-index safety system commonly uses pins 2 and 5.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":54,"auditFlag":false},{"id":"PDF2-055","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 31","sourcePage":31,"sourceNumber":"55","difficulty":"mixed","topic":"Medical gases & oxygen cylinders","question":"Roughly how much oxygen gas is contained in a full E-size O₂ cylinder?","options":["~160 L","~330 L","~660 L","~2000 L"],"correct":2,"explanation":"A full E-size oxygen cylinder typically contains about 660 L.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":55,"auditFlag":false},{"id":"PDF2-056","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 31","sourcePage":31,"sourceNumber":"56","difficulty":"mixed","topic":"Medical gases & oxygen cylinders","question":"What is the approximate pressure inside a full O₂ E-cylinder?","options":["~50 psi (pounds per square inch)","~200 psi","~2000 psi (≈137 bar)","~5000 psi"],"correct":2,"explanation":"A standard full compressed gas E-cylinder is around 2000 psig.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":56,"auditFlag":false},{"id":"PDF2-057","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 29","sourcePage":29,"sourceNumber":"57","difficulty":"mixed","topic":"Capnography & dead space","question":"A capnograph shows a near-zero end-tidal CO₂ reading in an intubated patient. The most likely cause is:","options":["A disconnected or leaking breathing circuit (or cardiac arrest leading to no pulmonary perfusion)","The patient is hyperventilating with normal cardiac output","The CO₂ analyzer is calibrated incorrectly (false reading)","Bronchospasm is causing incomplete alveolar emptying"],"correct":0,"explanation":"A sudden near-zero EtCO₂ can indicate disconnection, severe loss of perfusion or airway displacement.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":57,"auditFlag":false},{"id":"PDF2-058","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 29","sourcePage":29,"sourceNumber":"58","difficulty":"mixed","topic":"Capnography & dead space","question":"What is the normal gradient between end-tidal CO₂ (ETCO₂) and arterial CO₂ (PaCO₂) in a healthy adult?","options":["0 mm Hg (no difference)","~2 mm Hg (ETCO₂ higher than PaCO₂)","~4–6 mm Hg (PaCO₂ typically higher than ETCO₂)",">15 mm Hg difference (PaCO₂ much higher than ETCO₂)"],"correct":2,"explanation":"In healthy adults, PaCO₂ usually exceeds ETCO₂ by several mmHg.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":58,"auditFlag":false},{"id":"PDF2-059","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 29","sourcePage":29,"sourceNumber":"59","difficulty":"mixed","topic":"Capnography & dead space","question":"An increased ETCO₂–PaCO₂ gradient (i.e. PaCO₂ much higher than ETCO₂) indicates:","options":["Improved alveolar ventilation","Increased dead space ventilation (V/Q mismatch with high V/Q areas)","Calibration error in the capnometer","Increased CO₂ production (e.g. fever, sepsis)"],"correct":1,"explanation":"Dead-space ventilation increases the arterial/end-tidal CO₂ gradient.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":59,"auditFlag":false},{"id":"PDF2-060","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 29","sourcePage":29,"sourceNumber":"60","difficulty":"mixed","topic":"Capnography & dead space","question":"A patient's ETCO₂ is 30 mm Hg while PaCO₂ is 50 mm Hg. Which of the following is a likely cause of this widened gap?","options":["Hypoventilation","Pulmonary embolism (increased dead space in lungs)","Equipment malfunction causing false ETCO₂ reading","Hyperthermia increasing CO₂ production"],"correct":1,"explanation":"Pulmonary embolism can increase alveolar dead space.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":60,"auditFlag":false},{"id":"PDF2-061","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 29","sourcePage":29,"sourceNumber":"61","difficulty":"mixed","topic":"Respiratory physiology","question":"Which part of the upper respiratory tract is normally humidified to 100% relative humidity?","options":["Nasal passages","Oropharynx","Trachea","Bronchioles"],"correct":2,"explanation":"At body temperature, gas becomes fully saturated by the lower conducting airway (isothermic saturation boundary).","answerOrigin":"verified against course materials","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":61,"auditFlag":true,"auditNote":"The term 'upper respiratory tract' conflicts with the supplied answer 'trachea'."},{"id":"PDF2-062","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 29","sourcePage":29,"sourceNumber":"62","difficulty":"mixed","topic":"Respiratory physiology","question":"During an acute hemolytic transfusion reaction in a patient, what change is likely to be observed in end-tidal CO₂ (assuming the patient is intubated and monitored)?","options":["ETCO₂ increases significantly","ETCO₂ drops (decreases)","No change in ETCO₂","ETCO₂ waveform becomes erratic but mean value unchanged"],"correct":1,"explanation":"In a severe reaction with shock, reduced pulmonary perfusion can cause EtCO₂ to fall.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":62,"auditFlag":false},{"id":"PDF2-063","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 29","sourcePage":29,"sourceNumber":"63","difficulty":"mixed","topic":"Respiratory physiology","question":"Which three organs have the highest oxygen consumption (VO₂) in the body?","options":["Brain, liver, and heart","Brain, kidneys, and skeletal muscle","Heart, kidneys, and lungs","Liver, gastrointestinal tract, and brain"],"correct":0,"explanation":"The source identifies brain, liver and heart as major contributors to resting whole-body oxygen use.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":63,"auditFlag":false},{"id":"PDF2-064","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 30","sourcePage":30,"sourceNumber":"64","difficulty":"mixed","topic":"Respiratory physiology","question":"For a woman in her third trimester of pregnancy, which of the following changes in lung volumes/capacities is correct (compared to pre-pregnancy)?","options":["Functional Residual Capacity (FRC) increases, Closing Capacity (CC) unchanged","FRC decreases, CC increases","FRC decreases, CC decreases","FRC unchanged, CC increases"],"correct":1,"explanation":"Late pregnancy lowers FRC and increases airway-closure risk.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":64,"auditFlag":false},{"id":"PDF2-065","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 30","sourcePage":30,"sourceNumber":"65","difficulty":"mixed","topic":"Airway and critical care","question":"About one hour after a tracheostomy, the patient has significant bleeding at the tracheostomy stoma. What is the first action that should be taken?","options":["Apply firm pressure dressing over the stoma","Remove the tracheostomy tube and call the surgical team immediately","Inflate the trach cuff to tamponade bleeding and monitor","Pack the stoma with gauze and continue observation"],"correct":2,"explanation":"For major tracheostomy bleeding, maintain the airway, call emergency/surgical help and consider cuff hyperinflation as temporisation. The printed choices do not include the complete response.","answerOrigin":"verified against course materials","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":65,"auditFlag":true,"auditNote":"Major tracheostomy bleeding needs emergency help/airway management; choices omit full response."},{"id":"PDF2-066","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 30","sourcePage":30,"sourceNumber":"66","difficulty":"mixed","topic":"Airway and critical care","question":"A suction catheter cannot be passed through a patient's tracheostomy tube (in a ventilated patient). What is the recommended immediate management?","options":["Instill sterile saline into the trach tube and attempt suction again","Remove the tracheostomy tube and ventilate the patient (e.g. via bag-mask or oral ETT), while checking for adequate CO₂ return","Increase the suction pressure and use a smaller catheter","Advance a guidewire to clear the blockage if possible"],"correct":1,"explanation":"An obstructed tracheostomy is an airway emergency; use an established tracheostomy emergency algorithm to restore oxygenation and ventilation.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":66,"auditFlag":false},{"id":"PDF2-067","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 30","sourcePage":30,"sourceNumber":"67","difficulty":"mixed","topic":"Airway and critical care","question":"A mechanically ventilated patient has frequent episodes of pink, frothy secretions consistent with acute pulmonary edema. What adjustment should be made?","options":["Minimize suctioning to avoid airway trauma","Continue aggressive suctioning until secretions clear, and increase PEEP to help re-expand alveoli","Decrease PEEP to reduce capillary transudation","Switch to pressure control mode"],"correct":1,"explanation":"PEEP may improve alveolar recruitment and oxygenation, with suction as clinically needed.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":67,"auditFlag":false},{"id":"PDF2-068","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 30","sourcePage":30,"sourceNumber":"68","difficulty":"mixed","topic":"Airway and critical care","question":"A chest tube inserted for pneumothorax is noted to have continuous bubbling. How should this be managed?","options":["Immediately clamp the chest tube to stop air leak","Connect the chest tube to wall suction with an underwater seal drainage system (apply appropriate suction level)","Remove and reinsert a new chest tube in case of malposition","Increase the tidal volume on the ventilator to seal the leak"],"correct":1,"explanation":"The source's option B represents standard water-seal drainage with prescribed suction; continuous bubbling requires assessment for an air leak, not indiscriminate clamping.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":68,"auditFlag":true,"auditNote":"Continuous bubbling requires air-leak assessment; do not clamp a functioning tube reflexively."},{"id":"PDF2-069","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 30","sourcePage":30,"sourceNumber":"69","difficulty":"mixed","topic":"Airway and critical care","question":"The flow–volume loop on the ventilator is often examined to:","options":["Measure the patient's inspiratory muscle strength","Adjust the tidal volume setting","Identify patterns suggestive of underlying lung pathology (e.g. obstructive vs restrictive)","Estimate anatomical dead space from the flow curve"],"correct":2,"explanation":"Flow–volume shape may identify obstructive or restrictive respiratory mechanics.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":69,"auditFlag":false},{"id":"PDF2-070","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 30","sourcePage":30,"sourceNumber":"70","difficulty":"mixed","topic":"Airway and critical care","question":"How can \"breath stacking\" or auto-PEEP be detected and prevented during mechanical ventilation?","options":["By ensuring that expiratory flow returns to zero before the next breath begins (sufficient expiratory time)","By shortening the expiratory phase to cycle breaths faster","By using an inverse I:E ratio (longer inspiration)","By increasing tidal volume so fewer breaths are needed"],"correct":0,"explanation":"Verify complete exhalation on the flow-time scalar and extend exhalation when needed.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":70,"auditFlag":false},{"id":"PDF2-071","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 54","sourcePage":54,"sourceNumber":"71","difficulty":"mixed","topic":"Lung mechanics & respiratory care","question":"Pulmonary edema has what effect on lung compliance?","options":["It markedly increases compliance","It decreases compliance (stiff, heavy lungs)","No effect on compliance","It only affects airway resistance, not compliance"],"correct":1,"explanation":"Fluid-filled, heavy lungs become less compliant.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":71,"auditFlag":false},{"id":"PDF2-072","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 54","sourcePage":54,"sourceNumber":"72","difficulty":"mixed","topic":"Lung mechanics & respiratory care","question":"Which ventilator adjustment helps re-expand flooded or collapsed alveoli and push fluid out of alveolar spaces in acute pulmonary edema?","options":["Lowering tidal volume","Applying PEEP (positive end-expiratory pressure)","Reducing respiratory rate","Switching to 100% FiO₂ alone (no PEEP)"],"correct":1,"explanation":"PEEP recruits alveoli, improves FRC and gas exchange.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":72,"auditFlag":false},{"id":"PDF2-073","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 54","sourcePage":54,"sourceNumber":"73","difficulty":"mixed","topic":"Lung mechanics & respiratory care","question":"According to the Berlin Definition of ARDS, the syndrome is defined by acute onset within what time frame of a known clinical insult?","options":["24 hours","48 hours","1 week","1 month"],"correct":2,"explanation":"ARDS develops within one week of a known insult or new/worsening respiratory symptoms.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":73,"auditFlag":false},{"id":"PDF2-074","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 54","sourcePage":54,"sourceNumber":"74","difficulty":"mixed","topic":"Lung mechanics & respiratory care","question":"How does dynamic compliance (measured during active ventilation) generally compare to static compliance (measured during a no-flow breath-hold)?","options":["Dynamic compliance is usually higher than static compliance","Dynamic compliance is usually lower than static compliance (due to airway resistance during flow)","They are equal in healthy lungs and diverge only in pathology","Dynamic compliance relates to chest wall, static to lung – they are unrelated"],"correct":1,"explanation":"Resistive pressure during flow reduces calculated dynamic compliance.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":74,"auditFlag":false},{"id":"PDF2-075","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 54","sourcePage":54,"sourceNumber":"75","difficulty":"mixed","topic":"Lung mechanics & respiratory care","question":"Ventilator alarm limits are often set ~10–20% above and below the target values. What is the primary purpose of this range?","options":["To avoid false alarms and alarm fatigue","To alert clinicians to significant deviations from the patient's set or expected parameters","Because ventilator measurements are imprecise within ±10–20%","To comply with standard protocols that require a ±20% margin"],"correct":1,"explanation":"The primary purpose is detection of clinically meaningful deviations while retaining appropriate specificity.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":75,"auditFlag":false},{"id":"PDF2-076","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 54","sourcePage":54,"sourceNumber":"76","difficulty":"mixed","topic":"Lung mechanics & respiratory care","question":"If a person holds their breath, approximately how much does their arterial CO₂ (PaCO₂) rise per minute (in an average adult)?","options":["~1 mm Hg per minute","~3 mm Hg per minute","~5 mm Hg per minute","~10 mm Hg per minute"],"correct":1,"explanation":"The source estimates a roughly 3 mmHg/minute rise during apnoea; individual rates vary.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":76,"auditFlag":false},{"id":"PDF2-077","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 54","sourcePage":54,"sourceNumber":"77","difficulty":"mixed","topic":"Lung mechanics & respiratory care","question":"Certain drugs can depress central respiratory drive. Which of the following shifts the CO₂ response curve to the right (blunting the ventilatory response to CO₂)?","options":["Aspirin (salicylates)","Opiates (opioid analgesics)","Doxapram (respiratory stimulant)","Alkaline IV infusion (raising blood pH)"],"correct":1,"explanation":"Opioids decrease responsiveness of central respiratory centres.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":77,"auditFlag":false},{"id":"PDF2-078","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 55","sourcePage":55,"sourceNumber":"78","difficulty":"mixed","topic":"Lung mechanics & respiratory care","question":"Prolonged exposure to a high FiO₂ (e.g. 100% oxygen for days) primarily risks causing:","options":["Absorptive atelectasis but not lung injury","Oxygen toxicity leading to acute lung injury","CO₂ retention (hypercapnia) due to Haldane effect","Upper airway damage (drying of mucosa) but no effect on lungs"],"correct":1,"explanation":"High FiO₂ over time can lead to oxygen toxicity and absorption atelectasis.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":78,"auditFlag":false},{"id":"PDF2-079","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 55","sourcePage":55,"sourceNumber":"79","difficulty":"mixed","topic":"NIV and procedural safety","question":"For a patient on positive pressure ventilation (IPPV), at what point in the respiratory cycle should a chest tube be removed to minimize risk of air entry?","options":["At end-expiration","During a breath hold (inspiratory pause)","During inspiration (while positive pressure is applied)","Just after an exhalation, before the next inhale begins"],"correct":0,"explanation":"The source presents end-expiration. Option D is effectively the same timing, making the original item ambiguous; use local chest-drain removal protocol. Both A and D will be accepted because they describe end-expiration.","answerOrigin":"verified against course materials","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":79,"auditFlag":true,"auditNote":"Options A and D describe nearly the same point in the respiratory cycle.","alsoCorrect":[3]},{"id":"PDF2-080","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 55","sourcePage":55,"sourceNumber":"80","difficulty":"mixed","topic":"NIV and procedural safety","question":"Which of the following is an absolute contraindication for starting Non-Invasive Ventilation (NIV) support (e.g. BiPAP) in acute respiratory failure?","options":["COPD exacerbation with hypercapnia","Cardiogenic pulmonary edema with dyspnea","Inability to protect airway or severe altered mental status","Type 2 respiratory failure (hypercapnic respiratory failure)"],"correct":2,"explanation":"NIV requires adequate airway protection.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":80,"auditFlag":false},{"id":"PDF2-081","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 55","sourcePage":55,"sourceNumber":"81","difficulty":"mixed","topic":"NIV and procedural safety","question":"A key advantage of Non-Invasive Ventilation (NIV) in appropriate patients is:","options":["It completely protects the airway from aspiration","It avoids the need for endotracheal intubation and its associated complications","It guarantees a set tidal volume regardless of leaks","It eliminates the need for ICU monitoring"],"correct":1,"explanation":"In selected patients NIV can avoid invasive airway-related complications.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":81,"auditFlag":false},{"id":"PDF2-082","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 55","sourcePage":55,"sourceNumber":"82","difficulty":"mixed","topic":"NIV and procedural safety","question":"What is Hypoxic Pulmonary Vasoconstriction (HPV)?","options":["A pathological reflex that worsens ventilation–perfusion mismatch","A normal compensatory mechanism that diverts blood flow away from poorly oxygenated alveoli (improving V/Q matching)","A side effect of high PEEP ventilation","An experimental therapy involving pulmonary artery constriction"],"correct":1,"explanation":"HPV shifts blood flow away from hypoxic alveoli.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":82,"auditFlag":false},{"id":"PDF2-083","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 55","sourcePage":55,"sourceNumber":"83","difficulty":"mixed","topic":"NIV and procedural safety","question":"Which of the following describes a classic \"40–40\" recruitment maneuver to re-expand collapsed lung units?","options":["Applying 100% FiO₂ for 40 minutes before suctioning","Sustaining an inspiratory pressure of ~40 cm H₂O for ~40 seconds (then releasing)","Increasing PEEP to 40 cm H₂O for 40 consecutive breaths","Rapidly delivering 40 deep breaths in a row using manual bagging"],"correct":1,"explanation":"The source describes a sustained high-pressure 40/40 manoeuvre; this is a high-risk intervention, not routine bedside practice.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":83,"auditFlag":true,"auditNote":"40-for-40 manoeuvre is a historical approach requiring specialist supervision."},{"id":"PDF2-084","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 55","sourcePage":55,"sourceNumber":"84","difficulty":"mixed","topic":"NIV and procedural safety","question":"How do you distinguish inspiratory stridor from expiratory wheezing on clinical examination?","options":["Stridor occurs during inspiration and suggests upper airway (extrathoracic) obstruction, whereas wheezing on expiration indicates lower airway obstruction","Stridor is an expiratory sound; wheezing is inspiratory","Stridor has a musical tone while wheezing is a low-pitched harsh sound","There is no difference; both terms describe the same finding"],"correct":0,"explanation":"Inspiratory stridor suggests upper-airway obstruction while expiratory wheeze often reflects lower-airway disease.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":84,"auditFlag":false},{"id":"PDF2-085","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 52","sourcePage":52,"sourceNumber":"85","difficulty":"mixed","topic":"Monitoring & acute respiratory care","question":"Which of these is an acute effect of significant hypercapnia (high CO₂ levels) on the body?","options":["Cerebral vasodilation (increased intracranial pressure)","Peripheral vasoconstriction","Decreased respiratory drive","Reduced cardiac output due to bradycardia"],"correct":0,"explanation":"Elevated PaCO₂ produces cerebral vasodilation and can raise ICP.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":85,"auditFlag":false},{"id":"PDF2-086","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 52","sourcePage":52,"sourceNumber":"86","difficulty":"mixed","topic":"Monitoring & acute respiratory care","question":"Which parameter is the best indicator of adequate ventilation in a patient?","options":["PaCO₂ (arterial CO₂) level","PaO₂ (arterial O₂) level","Arterial pH","SpO₂ (oxygen saturation)"],"correct":0,"explanation":"PaCO₂ directly reflects adequacy of CO₂ clearance by alveolar ventilation.","answerOrigin":"verified against course materials","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":86,"auditFlag":false},{"id":"PDF2-087","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 52","sourcePage":52,"sourceNumber":"87","difficulty":"mixed","topic":"Monitoring & acute respiratory care","question":"What is the typical partial pressure of oxygen in the alveoli (PAO₂) at sea level on room air (approximate)?","options":["~150 mmHg","~100 mmHg","~50 mmHg","~40 mmHg"],"correct":1,"explanation":"Using alveolar gas equation on room air gives approximately 100 mmHg.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":87,"auditFlag":false},{"id":"PDF2-088","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 52","sourcePage":52,"sourceNumber":"88","difficulty":"mixed","topic":"Monitoring & acute respiratory care","question":"Which of the following will tend to increase a patient's PaCO₂?","options":["Doubling the tidal volume on the ventilator","Increasing dead space (e.g. adding a long connector tube)","Increasing respiratory rate","Using pressure support ventilation instead of assist-control"],"correct":1,"explanation":"Increased dead space reduces effective alveolar ventilation at the same overall VT and RR.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":88,"auditFlag":false},{"id":"PDF2-089","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 52","sourcePage":52,"sourceNumber":"89","difficulty":"mixed","topic":"Monitoring & acute respiratory care","question":"An alarm indicates high peak inspiratory pressure on the ventilator. All of the following are potential causes except:","options":["Patient coughing or biting the tube","Bronchospasm or narrowed airways","Circuit disconnection","Mucus plugging of the endotracheal tube"],"correct":2,"explanation":"Disconnection typically produces a low-pressure or low-volume alarm rather than a high-pressure alarm.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":89,"auditFlag":false},{"id":"PDF2-090","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 52","sourcePage":52,"sourceNumber":"90","difficulty":"mixed","topic":"Monitoring & acute respiratory care","question":"During CPR on a ventilated patient, an ETCO₂ reading of <10 mmHg suggests:","options":["High quality chest compressions with good perfusion","Poor cardiac output from ineffective compressions (or patient likely has little to no circulation)","The patient is being ventilated too slowly","The endotracheal tube is in the right main bronchus"],"correct":1,"explanation":"Persistently low EtCO₂ during CPR can suggest inadequate pulmonary blood flow.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":90,"auditFlag":false},{"id":"PDF2-091","examId":"mock2","source":"vims question and answer.pdf — PDF page 9","sourcePage":9,"sourceNumber":"2","difficulty":"mixed","topic":"VIMS recall MCQs","question":"A patient with previous total laryngectomy presents with a blocked tracheostomy tube. What is the MOST appropriate action?","options":["Intubate via oral","Bag via mouth","Ventilate via stoma","Apply nasal oxygen"],"correct":2,"explanation":"Following total laryngectomy the upper airway is disconnected; oxygenate/ventilate through the neck stoma.","answerOrigin":"verified against course materials","calculation":false,"sourceFile":"vims question and answer.pdf","originQuestion":"2","auditFlag":true,"auditNote":"Total laryngectomy anatomy is permanent stoma-only ventilation; wording mixes tracheostomy terminology."},{"id":"PDF2-092","examId":"mock2","source":"vims question and answer.pdf — PDF page 9","sourcePage":9,"sourceNumber":"3","difficulty":"mixed","topic":"VIMS recall MCQs","question":"Which of the following changes occur with normal aging?","options":["Decreased FRC","Decreased closing capacity","Increased lung compliance","Increased lung elastic recoil?"],"correct":2,"explanation":"Aging generally reduces lung elastic recoil and raises lung compliance and closing capacity.","answerOrigin":"verified against course materials","calculation":false,"sourceFile":"vims question and answer.pdf","originQuestion":"3","auditFlag":false},{"id":"PDF2-093","examId":"mock2","source":"vims question and answer.pdf — PDF page 6","sourcePage":6,"sourceNumber":"5","difficulty":"mixed","topic":"VIMS recall MCQs","question":"What are the normal physiological shunt in healthy individuals?","options":["1%","5%","10%","20%"],"correct":1,"explanation":"A normal physiological shunt fraction is commonly about 2–5%.","answerOrigin":"verified against course materials","calculation":false,"sourceFile":"vims question and answer.pdf","originQuestion":"5","auditFlag":false},{"id":"PDF2-094","examId":"mock2","source":"vims question and answer.pdf — PDF page 9","sourcePage":9,"sourceNumber":"4","difficulty":"mixed","topic":"VIMS recall MCQs","question":"Which organ has the highest oxygen consumption per 100 g of tissue?","options":["Brain","Liver","Kidney","Heart"],"correct":3,"explanation":"The heart has the highest oxygen use per 100 g tissue among these options at rest; this differs from total oxygen consumption by an organ.","answerOrigin":"verified against course materials","calculation":false,"sourceFile":"vims question and answer.pdf","originQuestion":"4","auditFlag":false},{"id":"PDF2-095","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 52","sourcePage":52,"sourceNumber":"95","difficulty":"mixed","topic":"Asynchrony & troubleshooting","question":"What is a normal range for static compliance of the lungs in an adult on a ventilator?","options":["~10–20 mL/cm H₂O","~30–50 mL/cm H₂O","~70–100 mL/cm H₂O","~150–200 mL/cm H₂O"],"correct":1,"explanation":"The source marks ~30–50 mL/cm H₂O as a representative range for mechanically ventilated respiratory system compliance.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":95,"auditFlag":false},{"id":"PDF2-096","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 52","sourcePage":52,"sourceNumber":"96","difficulty":"mixed","topic":"Asynchrony & troubleshooting","question":"A ventilator that auto-triggers (delivers unintended breaths without patient effort) might be caused by:","options":["The patient coughing or moving in bed","An air leak in the endotracheal tube cuff or circuit causing pressure oscillations","The sensitivity being set too low (too insensitive)","The patient being over-sedated and not initiating breaths"],"correct":1,"explanation":"Leaks and circuit oscillations can trigger unintended breaths.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":96,"auditFlag":false},{"id":"PDF2-097","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 53","sourcePage":53,"sourceNumber":"97","difficulty":"mixed","topic":"Asynchrony & troubleshooting","question":"In volume-controlled ventilation, which setting issue can lead to flow asynchrony (mismatch between patient demand and delivered flow)?","options":["An inappropriate inspiratory flow rate setting (too high or too low for patient's needs)","Auto-PEEP presence","Leak in the ventilator circuit","Excessive use of analgesics"],"correct":0,"explanation":"Inspiratory flow must match patient demand to minimise flow starvation or other asynchrony.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":97,"auditFlag":false},{"id":"PDF2-098","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 53","sourcePage":53,"sourceNumber":"98","difficulty":"mixed","topic":"Asynchrony & troubleshooting","question":"Delayed cycling (termination of inspiration later than the patient's neural inspiratory time) in volume control mode is often due to:","options":["Too short an inspiratory time","An excessively long set inspiratory time or very large tidal volume","The patient triggering additional breaths","Premature cycling-off by the ventilator"],"correct":1,"explanation":"Ventilator inspiration that lasts longer than neural inspiration causes delayed cycling.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":98,"auditFlag":false},{"id":"PDF2-099","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 53","sourcePage":53,"sourceNumber":"99","difficulty":"mixed","topic":"Asynchrony & troubleshooting","question":"Which of the following is not a form of patient–ventilator dyssynchrony?","options":["Auto-triggering","Ineffective (missed) inspiratory efforts","Double triggering (breath stacking)","Perfect patient–ventilator synchrony"],"correct":3,"explanation":"Perfect synchrony by definition is not dyssynchrony.","answerOrigin":"verified against course materials","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":99,"auditFlag":false},{"id":"PDF2-100","examId":"mock2","source":"Mock exam preparation .pdf — PDF page 53","sourcePage":53,"sourceNumber":"100","difficulty":"mixed","topic":"Asynchrony & troubleshooting","question":"When performing bronchoscopic suctioning via an endotracheal tube in a hypoxemic patient, what is recommended regarding the bronchoscope size?","options":["Use the largest bronchoscope that can fit to clear secretions quickly","Use a bronchoscope about half the internal diameter of the ETT (to minimize airway obstruction during the procedure)","Bronchoscopy should never be performed via an ETT","Bronchoscope size is irrelevant as long as FiO₂ is 100% during the procedure"],"correct":1,"explanation":"A smaller bronchoscope relative to ETT internal diameter preserves airflow during bronchoscopy.","answerOrigin":"marked in source","calculation":false,"sourceFile":"Mock exam preparation .pdf","originQuestion":100,"auditFlag":false}]};